INSERT INTO listening_pods (id, course_code, pod_type, slug, title, scene, difficulty, speakers, source_file, metadata, visibility) VALUES (
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC001-S0001', 'cym_n_for_eng:senedd-s4c-steve', 1, 1, 1, 'Delyth Jewell', 'Prynhawn da.', 'Good afternoon.', 'contribution 555122 · part 1/4', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC001-S0002', 'cym_n_for_eng:senedd-s4c-steve', 1, 2, 2, 'Delyth Jewell', 'Hoffwn i groesawu''r Aelodau''n ôl i''r cyfarfod hwn o''r Pwyllgor Diwylliant, Cyfathrebu, y Gymraeg, Chwaraeon a Chysylltiadau Rhyngwladol.', 'I''d like to welcome Members back to this meeting of the Culture, Communications, Welsh Language, Sport and International Relations Committee.', 'contribution 555122 · part 2/4', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC001-S0003', 'cym_n_for_eng:senedd-s4c-steve', 1, 3, 3, 'Delyth Jewell', 'Bydda i nawr yn symud ymlaen at sesiwn dystiolaeth gydag S4C ynglŷn ag honiadau am fwlio yn y sianel.', 'We''ll now move to an evidence session with S4C regarding allegations concerning bullying at the channel.', 'contribution 555122 · part 3/4', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC001-S0004', 'cym_n_for_eng:senedd-s4c-steve', 1, 4, 4, 'Delyth Jewell', 'Mi wna i ofyn i''n tystion i gyflwyno eu hunain ar gyfer y record.', 'I''ll ask our witnesses to introduce themselves for the record.', 'contribution 555122 · part 4/4', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC002-S0005', 'cym_n_for_eng:senedd-s4c-steve', 2, 5, 5, 'Rhodri Williams', 'Rhodri Williams ydw i, cadeirydd S4C.', 'I''m Rhodri Williams, chair of S4C.', 'contribution 555157 · part 1/1', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC003-S0006', 'cym_n_for_eng:senedd-s4c-steve', 3, 6, 6, 'Chris Jones', 'Chris Jones, aelod anweithredol o fwrdd S4C.', 'Chris Jones, non-executive member of the S4C board.', 'contribution 555159 · part 1/1', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC004-S0007', 'cym_n_for_eng:senedd-s4c-steve', 4, 7, 7, 'Delyth Jewell', 'Diolch.', 'Thank you.', 'contribution 555161 · part 1/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC004-S0008', 'cym_n_for_eng:senedd-s4c-steve', 4, 8, 8, 'Delyth Jewell', 'Mi wnaf i ofyn os oes gan unrhyw Aelodau fuddiannau i''w datgan.', 'I''ll ask whether any Members have any declarations of interest.', 'contribution 555161 · part 2/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC005-S0009', 'cym_n_for_eng:senedd-s4c-steve', 5, 9, 9, 'Alun Davies', 'Gaf i jest roi ar y record—?', 'Could I just put on record—?', 'contribution 555164 · part 1/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC005-S0010', 'cym_n_for_eng:senedd-s4c-steve', 5, 10, 10, 'Alun Davies', 'Dyw e ddim yn fuddiant or ran y rheolau, ond dwi''n credu y dylwn i nodi ar y record cyhoeddus roeddwn i arfer bod yn aelod o dîm rheoli S4C a dwi''n nabod y ddau dyst o''n blaenau ni y prynhawn yma.', 'It''s not an interest in terms of Standing Orders, but I do think I should place on the public record that I used to be a member of the management team at S4C and I know both witnesses before us this afternoon.', 'contribution 555164 · part 2/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC006-S0011', 'cym_n_for_eng:senedd-s4c-steve', 6, 11, 11, 'Delyth Jewell', 'Diolch, Alun.', 'Thank you, Alun.', 'contribution 555182 · part 1/19', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC006-S0012', 'cym_n_for_eng:senedd-s4c-steve', 6, 12, 12, 'Delyth Jewell', 'Mae''r sesiwn yma wedi ei aildrefnu ers 14 Rhagfyr y llynedd yn dilyn salwch annisgwyl ac anffodus y cyn brif weithredwr, Sian Doyle.', 'This session has been rearranged from 14 December last year following the unexpected and unfortunate illness of the former chief executive, Sian Doyle.', 'contribution 555182 · part 2/19', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC006-S0013', 'cym_n_for_eng:senedd-s4c-steve', 6, 13, 13, 'Delyth Jewell', 'Dŷn ni oll yn dymuno gwellhad buan iddi, wrth gwrs.', 'We all wish her a speedy recovery, of course.', 'contribution 555182 · part 3/19', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC006-S0014', 'cym_n_for_eng:senedd-s4c-steve', 6, 14, 14, 'Delyth Jewell', 'Cyn inni ddechrau heddiw hoffwn i roi ar gofnod pa mor bryderus mae''r digwyddiadau diweddar wedi bod.', 'Before we start today, I''d like to put on record how concerning recent events have been.', 'contribution 555182 · part 4/19', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC006-S0015', 'cym_n_for_eng:senedd-s4c-steve', 6, 15, 15, 'Delyth Jewell', 'Tra ei fod e’n fater wedi''i neilltuo i Lywodraeth y Deyrnas Gyfunol, mae S4C yn sefydliad unigryw.', 'While S4C is a matter reserved to the UK Government, it is a unique organisation.', 'contribution 555182 · part 5/19', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC006-S0016', 'cym_n_for_eng:senedd-s4c-steve', 6, 16, 16, 'Delyth Jewell', 'Mae gan bob un ohonon ni ddiddordeb personol yn llwyddiant y sianel.', 'Every one of us has a personal interest in the channel''s success.', 'contribution 555182 · part 6/19', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC006-S0017', 'cym_n_for_eng:senedd-s4c-steve', 6, 17, 17, 'Delyth Jewell', 'Mae gwaith y sianel dros y pedair degawd ddiwethaf o ran cynnwys Cymraeg yn rhywbeth y gallwn ni i gyd fod yn falch iawn ohono.', 'The channel''s work over the last four decades in providing Welsh language content is something that we can all be proud of.', 'contribution 555182 · part 7/19', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC006-S0018', 'cym_n_for_eng:senedd-s4c-steve', 6, 18, 18, 'Delyth Jewell', 'Mae gan S4C hefyd rôl bwysig i''w chwarae yn helpu i sicrhau’r nod o gyrraedd miliwn o siaradwyr Cymraeg erbyn 2050.', 'S4C also has an important role to play in assisting to deliver the aim of ensuring a million Welsh speakers by 2050.', 'contribution 555182 · part 8/19', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC006-S0019', 'cym_n_for_eng:senedd-s4c-steve', 6, 19, 19, 'Delyth Jewell', 'Fodd bynnag, fel y byddwch chi’n ymwybodol, mae difrifoldeb y sefyllfa ddiweddar wedi tanseilio enw da y sianel.', 'However, as you will be aware, the seriousness of the recent situation has undermined the channel''s reputation.', 'contribution 555182 · part 9/19', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC006-S0020', 'cym_n_for_eng:senedd-s4c-steve', 6, 20, 20, 'Delyth Jewell', 'Mae hynny''n destun pryder i ni i gyd.', 'This is a cause for concern for us all.', 'contribution 555182 · part 10/19', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC006-S0021', 'cym_n_for_eng:senedd-s4c-steve', 6, 21, 21, 'Delyth Jewell', 'Mi fydd ein sesiwn heddiw yn ffocysu ar yr ymateb sefydliadol yn dilyn yr adroddiad i mewn i''r amgylchedd gwaith a''r awyrgylch yn S4C, yn ogystal â chwestiynau am drefniadau llywodraethu S4C.', 'Our session today will focus on the organisational response following the report on the working environment and atmosphere at S4C, as well as questions on S4C''s governance arrangements.', 'contribution 555182 · part 11/19', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC006-S0022', 'cym_n_for_eng:senedd-s4c-steve', 6, 22, 22, 'Delyth Jewell', 'Does dim rhaid i fi ddweud pa mor bwysig yw hi eich bod chi yn adennill hyder y rheini sydd yn gweithio yn S4C, yn ogystal â gydag S4C, ynghyd â phobl Cymru sydd yn ddibynnol ar gynnwys S4C.', 'I don''t need to say how important it is that you restore the confidence of those who work in S4C, as well as with S4C, and the people of Wales who rely on S4C content.', 'contribution 555182 · part 12/19', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC006-S0023', 'cym_n_for_eng:senedd-s4c-steve', 6, 23, 23, 'Delyth Jewell', 'Dylai hyn fod yn sianel sy''n darparu darlledu gwasanaeth cyhoeddus o ansawdd uchel, unigryw ac annibynnol i bobl Cymru.', 'S4C should be a channel that provides high-quality, unique and independent public broadcasting to the people of Wales.', 'contribution 555182 · part 13/19', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC006-S0024', 'cym_n_for_eng:senedd-s4c-steve', 6, 24, 24, 'Delyth Jewell', 'Mae gennych chi gyfrifoldeb i adfer y niwed sydd wedi digwydd yn ddiweddar.', 'You have a responsibility to repair the recent damage caused.', 'contribution 555182 · part 14/19', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC006-S0025', 'cym_n_for_eng:senedd-s4c-steve', 6, 25, 25, 'Delyth Jewell', 'Ein gobaith ni yw y gallwn ni ddod at wraidd rhai o''r materion yma yn ein sesiwn heddiw a dechrau’r broses o adfer ein darlledwr cenedlaethol.', 'Our hope is that we can get to the root of some of these issues in our session today and start the process of rebuilding our national broadcaster.', 'contribution 555182 · part 15/19', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC006-S0026', 'cym_n_for_eng:senedd-s4c-steve', 6, 26, 26, 'Delyth Jewell', 'Hoffwn i nodi i''r rheini sydd yn gwylio heddiw y gallai trafodaethau’r sesiwn yma gynnwys themâu a allai beri gofid i rai.', 'I''d like to warn viewers watching today that this session''s proceedings could include themes that could cause distress for some people.', 'contribution 555182 · part 16/19', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC006-S0027', 'cym_n_for_eng:senedd-s4c-steve', 6, 27, 27, 'Delyth Jewell', 'Felly, mi wnawn ni fynd, os ydych chi’n hapus, yn syth i mewn i gwestiynau.', 'So, if you''re happy, we''ll go straight into questions.', 'contribution 555182 · part 17/19', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC006-S0028', 'cym_n_for_eng:senedd-s4c-steve', 6, 28, 28, 'Delyth Jewell', 'Beth ydych chi’n meddwl mae S4C wedi''i wneud i adfer sefydlogrwydd eich sefydliad ers cyhoeddi adroddiad Capital Law?', 'What do you think S4C has done to restore stability in your organisation since the Capital Law report was published?', 'contribution 555182 · part 18/19', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC006-S0029', 'cym_n_for_eng:senedd-s4c-steve', 6, 29, 29, 'Delyth Jewell', 'Beth ydy''r camau nesaf y byddwch chi’n eu cymryd?', 'And what are the next steps you''ll be taking?', 'contribution 555182 · part 19/19', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC007-S0030', 'cym_n_for_eng:senedd-s4c-steve', 7, 30, 30, 'Rhodri Williams', 'Y peth cyntaf sydd wedi digwydd, o ran darparu sefydlogrwydd, yw rhoi trefniadau dros dro mewn lle, lle mae dyletswyddau''r prif weithredwr a''r prif swyddog cynnwys yn cael eu rhannu gan Elin Morris, prif swyddog gweithredol, a Geraint Evans, cyfarwyddwr strategaeth cynnwys a chyhoeddi.', 'The first thing that''s happened, in terms of providing stability, is that we''ve put interim arrangements in place where the duties and responsibilities of the chief executive and chief content officer are shared by Elin Morris, the chief operating officer, and Geraint Evans, the director of content and publication strategy.', 'contribution 555255 · part 1/15', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC007-S0031', 'cym_n_for_eng:senedd-s4c-steve', 7, 31, 31, 'Rhodri Williams', 'Mae hynny wedi llwyddo i greu sefydlogrwydd ac mae e wedi llwyddo i wneud ein staff—.', 'That has given us some stability and it has succeeded in making our staff—.', 'contribution 555255 · part 2/15', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC007-S0032', 'cym_n_for_eng:senedd-s4c-steve', 7, 32, 32, 'Rhodri Williams', 'Ac i fi, a liciwn i bwysleisio hyn ar y cychwyn, y flaenoriaeth fan hyn, yr hyn sydd yn ganolog i''r holl gwestiwn yma, yw lles a diogelwch ein staff ni, ac maen nhw wedi ymateb yn bositif i''r trefniadau newydd hynny.', 'And for me, and I''d like to emphasise this point at the very outset, the priority here, and what is central to this whole question, is the well-being and safety of our staff, and they have responded positively to those new arrangements.', 'contribution 555255 · part 3/15', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC007-S0033', 'cym_n_for_eng:senedd-s4c-steve', 7, 33, 33, 'Rhodri Williams', 'Maen nhw''n deall, wrth gwrs, mai trefniadau dros dro ydyn nhw.', 'They understand, of course, that they are interim arrangements.', 'contribution 555255 · part 4/15', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC007-S0034', 'cym_n_for_eng:senedd-s4c-steve', 7, 34, 34, 'Rhodri Williams', 'Maes o law, mi fydd angen penodi prif weithredwr parhaol, llawnamser, ac efallai mater i''r prif weithredwr, mewn ymgynghoriad gyda''r bwrdd, fydd penderfynu ar siâp y tîm rheoli.', 'In due course, we will need to appoint a permanent, full-time chief executive, and then, perhaps, it will be a matter for the chief executive, in consultation with the board, to decide on the shape of the management team.', 'contribution 555255 · part 5/15', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC007-S0035', 'cym_n_for_eng:senedd-s4c-steve', 7, 35, 35, 'Rhodri Williams', 'Dyw e ddim o angenrheidrwydd yn golygu llenwi y swyddi oedd yn y patrwm blaenorol.', 'It doesn''t necessarily mean that we will fill those roles that existed in the previous regime.', 'contribution 555255 · part 6/15', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC007-S0036', 'cym_n_for_eng:senedd-s4c-steve', 7, 36, 36, 'Rhodri Williams', 'Roeddwn i''n falch iawn, fel y gallwch chi ddychmygu, i weld ymhlith papurau’r pwyllgor ar gyfer heddiw eich bod chi wedi cael ymateb gan BECTU sydd yn cadarnhau yr hyn dwi''n ei ddweud, mai nid fy adlewyrchiad i yw e ar y ffaith bod staff bellach yn hapus—mae BECTU yn cadarnhau hynny.', 'I was very pleased, as you can imagine, to see among the committee''s papers for today that you had received a response from BECTU that confirms what I am saying. It''s not my reflection on the fact that staff are now happier—BECTU confirm that.', 'contribution 555255 · part 7/15', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC007-S0037', 'cym_n_for_eng:senedd-s4c-steve', 7, 37, 37, 'Rhodri Williams', 'Maen nhw wedi cael, os dwi''n deall yn iawn, dau gyfarfod gydag aelodau staff o fewn S4C, un ym mis Rhagfyr ac un dydd Gwener wythnos diwethaf, ac mae''r ymateb yn bositif.', 'As I understand it, they''ve had two meetings with staff members within S4C, one in December and one Friday of last week, and the response has been positive.', 'contribution 555255 · part 8/15', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC007-S0038', 'cym_n_for_eng:senedd-s4c-steve', 7, 38, 38, 'Rhodri Williams', 'Felly, dyna’r cam cyntaf, os liciwch chi.', 'So, that''s the first step, if you like.', 'contribution 555255 · part 9/15', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC007-S0039', 'cym_n_for_eng:senedd-s4c-steve', 7, 39, 39, 'Rhodri Williams', 'Y cam nesaf, ac efallai y down ni at hwn maes o law, yw i edrych ar yr hyn nawr sydd eisiau—.', 'The next step, and perhaps we will come to this in due course, is to look at what needs to be—.', 'contribution 555255 · part 10/15', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC007-S0040', 'cym_n_for_eng:senedd-s4c-steve', 7, 40, 40, 'Rhodri Williams', 'Byddwn i''n cytuno 100 y cant gyda’ch sylwadau chi, Gadeirydd, bod angen ailennyn hyder yn y sefydliad, oherwydd o''r foment derbynion ni''r llythyr cyntaf hwnnw, fel aelodau anweithredol y bwrdd, ar 28 Ebrill y llynedd, yn codi''r pryderon yma—a nid yn eu codi nhw gydag S4C am y tro cyntaf ond yn eu codi nhw gyda ni fel aelodau anweithredol am y tro cyntaf—dwi''n credu cafodd llawer o niwed ei wneud i enw da''r sefydliad, i hyder y sefydliad, i hunan-barch llawer o bobl.', 'I would agree 100 per cent with your comments, Chair, that we do need to rebuild confidence in the organisation, because from the moment we received that first letter, as non-executive members of the board, on 28 April of last year, raising these concerns—not raising them with S4C for the first time but raising them with us as non-executive members for the first time—I do think that a great deal of damage was done to the reputation of the organisation, to the confidence of the organisation and to the self-respect of many people.', 'contribution 555255 · part 11/15', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC007-S0041', 'cym_n_for_eng:senedd-s4c-steve', 7, 41, 41, 'Rhodri Williams', 'Mae e wedi bod y cyfnod anoddaf, byddwn i''n meddwl, yn hanes S4C.', 'It has been the most difficult period in the history of S4C, I would think.', 'contribution 555255 · part 12/15', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC007-S0042', 'cym_n_for_eng:senedd-s4c-steve', 7, 42, 42, 'Rhodri Williams', 'Felly, fel rhan o''r broses honno—ac eto, liciwn i gyfeirio at lythyr BECTU, lle maen nhw''n gwneud awgrymiadau—rŷn ni''n awyddus i weithio gyda nhw, gyda''n staff, i wneud yr hyn sydd ei angen i ailennill yr hyder hwnnw.', 'So, as part of that process—and again, I''d like to refer to the BECTU letter, where they make suggestions—we are eager to work with them and with our staff in order to do what is necessary to restore that confidence.', 'contribution 555255 · part 13/15', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC007-S0043', 'cym_n_for_eng:senedd-s4c-steve', 7, 43, 43, 'Rhodri Williams', 'Byddwn i''n ei roi e o dan bedwar penawd, sef arweinyddiaeth—ac mae hwn yn ymwneud, yn amlwg, â phenodi prif weithredwr newydd; diwylliant—creu diwylliant lle mae pobl yn gallu bod yn ddiogel yn eu gwaith a ddim yn byw mewn ofn; bod y polisïau presennol mewn lle, a bod y polisïau yn addas ar gyfer diogelu staff ac yn cynnig ffordd i bobl ddelio â phryderon sy''n codi; ac yn olaf, gyda llywodraethiant: oes yna faterion ynghylch y model llywodraethiant presennol sydd angen edrych arnyn nhw o''r newydd?', 'I would place it into four headings, and those are leadership—and that relates clearly to the appointment of a new chief executive; culture—the creation of a culture where people can feel safe at work and where they do not live in fear; that the current policies are in place and that those policies are fit to safeguard staff and do provide ways and means of dealing with concerns that arise; and finally in terms of governance: are there issues around the model of governance currently in place that need to be reviewed or looked at anew?', 'contribution 555255 · part 14/15', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC007-S0044', 'cym_n_for_eng:senedd-s4c-steve', 7, 44, 44, 'Rhodri Williams', 'Bydd angen mynd ati i wneud y cyfan yna yn ystod y misoedd sydd i ddod.', 'We will need to do all of that during the coming months.', 'contribution 555255 · part 15/15', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC008-S0045', 'cym_n_for_eng:senedd-s4c-steve', 8, 45, 45, 'Delyth Jewell', 'Diolch am hwnna.', 'Thank you for that.', 'contribution 555098 · part 1/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC008-S0046', 'cym_n_for_eng:senedd-s4c-steve', 8, 46, 46, 'Delyth Jewell', 'Gwnawn ni symud at Carolyn Thomas.', 'We''ll move on to Carolyn Thomas.', 'contribution 555098 · part 2/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC009-S0047', 'cym_n_for_eng:senedd-s4c-steve', 9, 47, 47, 'Carolyn Thomas', 'Prynhawn da.', 'Good afternoon.', 'contribution 555102 · part 1/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC009-S0048', 'cym_n_for_eng:senedd-s4c-steve', 9, 48, 48, 'Carolyn Thomas', 'Dwi''n mynd i siarad Saesneg.', 'I will be asking my questions in English.', 'contribution 555102 · part 2/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC010-S0049', 'cym_n_for_eng:senedd-s4c-steve', 10, 49, 49, 'Rhodri Williams', 'Os ydy e''n iawn, gwnaf i barhau i ateb yn Gymraeg.', 'If it''s okay, I''ll continue to answer in Welsh.', 'contribution 555110 · part 1/16', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC010-S0050', 'cym_n_for_eng:senedd-s4c-steve', 10, 50, 50, 'Rhodri Williams', 'Mae''r bwrdd yn cyfarfod nesaf bythefnos i heddiw, fel mae''n digwydd, ac yn y cyfarfod hwnnw mi fyddwn ni''n trafod pecyn o fesurau o dan y penawdau hynny.', 'The board is meeting next a fortnight today, as it happens, and in that meeting we will be discussing a package of measures under those headings.', 'contribution 555110 · part 2/16', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC010-S0051', 'cym_n_for_eng:senedd-s4c-steve', 10, 51, 51, 'Rhodri Williams', 'Mae peth o''r gwaith, fel byddech chi''n disgwyl, eisoes wedi dechrau.', 'Some of the work, as you would expect, has already begun.', 'contribution 555110 · part 3/16', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC010-S0052', 'cym_n_for_eng:senedd-s4c-steve', 10, 52, 52, 'Rhodri Williams', 'Mi fydd swyddogion wedi bod yn edrych ar rai o''r materion dwi newydd gyfeirio atyn nhw ac yn dod ag argymhellion gerbron, a byddwn ni''n rhoi prosesau mewn lle ar gyfer yr adolygu hynny sydd angen digwydd, a thrafodaeth ehangach.', 'By then, officials will have been looking at some of the issues that I''ve already referred to and will be bringing recommendations to that meeting, and we will put processes in place for that reviewing that needs to be done, and a wider discussion.', 'contribution 555110 · part 4/16', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC010-S0053', 'cym_n_for_eng:senedd-s4c-steve', 10, 53, 53, 'Rhodri Williams', 'Oherwydd, wrth gwrs, o ran polisïau, er enghraifft rhai sydd yn ymwneud â chwythu''r chwiban, parch yn y gweithle, disgyblaeth, cwynion, mae gyda ni bolisïau ar y rheini yn barod.', 'Because in terms of having policies such as those relating to whistleblowing, respect in the workplace, discipline, complaints, we have policies on those issues already.', 'contribution 555110 · part 5/16', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC010-S0054', 'cym_n_for_eng:senedd-s4c-steve', 10, 54, 54, 'Rhodri Williams', 'Byddwn ni am eu hadolygu nhw.', 'We will need to review those.', 'contribution 555110 · part 6/16', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC010-S0055', 'cym_n_for_eng:senedd-s4c-steve', 10, 55, 55, 'Rhodri Williams', 'Ond, wrth gwrs, beth mae adroddiad Capital Law yn ei ddweud wrthym ni yw nid problem gyda''r polisïau oedd yn achosi''r anawsterau y tu mewn i S4C a''r pryder a''r gofid i aelodau staff; diwylliant ac arweinyddiaeth S4C oedd yn creu''r problemau hynny.', 'But what Capital Law''s report tells us is that it wasn''t a problem with our policies that was causing the difficulties within S4C and the concerns among members of staff; the culture and the leadership of S4C was creating those problems.', 'contribution 555110 · part 7/16', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC010-S0056', 'cym_n_for_eng:senedd-s4c-steve', 10, 56, 56, 'Rhodri Williams', 'Mae''r adroddiad yn glir iawn ar hynny.', 'The report is very clear on that.', 'contribution 555110 · part 8/16', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC010-S0057', 'cym_n_for_eng:senedd-s4c-steve', 10, 57, 57, 'Rhodri Williams', 'Dwi ddim eisiau sôn yn ormodol am gwestiynau ddelion ni gyda nhw ddoe, ond mae yna berygl, dwi''n credu, fod pobl yn rhyw fath o ofn derbyn y gwir ynglŷn â''r hyn sydd wedi digwydd fan hyn, a bod yr hyn sydd yn yr adroddiad, a lles y staff a''n dyletswydd ni o ofal tuag at ein staff, rhywsut yn cael ei anwybyddu''n llwyr.', 'I don''t want to speak too much about questions that we dealt with yesterday, but there is a danger, I think, that people aren''t willing to accept the truth about what''s happened here, and that what is in the report on the welfare of staff and our duty of care towards staff is somewhat ignored completely.', 'contribution 555110 · part 9/16', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC010-S0058', 'cym_n_for_eng:senedd-s4c-steve', 10, 58, 58, 'Rhodri Williams', 'Byddwn i am bwysleisio fanna fod y dystiolaeth cawsom ni yn adroddiad Capital Law yn dangos yn glir iawn bod yn rhaid cael diwylliant lle mae pobl yn gallu bod yn ddiogel, lle''u bod nhw''n gallu mynegi amheuaeth a beirniadaeth heb ofni canlyniadau hynny.', 'I would want to emphasise there that the evidence we received in the Capital Law report shows clearly that there is a need for a culture where people can be safe, where they can express doubts and criticism without fear of consequences.', 'contribution 555110 · part 10/16', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC010-S0059', 'cym_n_for_eng:senedd-s4c-steve', 10, 59, 59, 'Rhodri Williams', 'Mae''r broses yna o newid diwylliannol yn gwbl allweddol i''n llwyddiant ni fel sefydliad yn y dyfodol.', 'That process of changing culture is key to our success as an organisation in the future.', 'contribution 555110 · part 11/16', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC010-S0060', 'cym_n_for_eng:senedd-s4c-steve', 10, 60, 60, 'Rhodri Williams', 'Wrth gwrs, mae e''n ein cynnwys ni fel bwrdd—fyddwn i ddim am ddiystyru ein rôl ni yn gosod yr esiampl yn hynny o beth.', 'Of course, that includes us as a board—I wouldn''t want to disregard our role in providing that example in that context.', 'contribution 555110 · part 12/16', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC010-S0061', 'cym_n_for_eng:senedd-s4c-steve', 10, 61, 61, 'Rhodri Williams', 'Mae e hefyd yn cynnwys yr arweinyddiaeth a''r staff.', 'It also includes the leadership and staff.', 'contribution 555110 · part 13/16', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC010-S0062', 'cym_n_for_eng:senedd-s4c-steve', 10, 62, 62, 'Rhodri Williams', 'Ond dwi yn credu, i''w wneud e''n llwyddiannus, byddwn i''n rhagweld y bydd eisiau cymorth allanol arnom ni.', 'But I do believe that, for that to be successful, I would foresee that there''s a need for external support.', 'contribution 555110 · part 14/16', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC010-S0063', 'cym_n_for_eng:senedd-s4c-steve', 10, 63, 63, 'Rhodri Williams', 'Fe soniais i am drefniadau llywodraethiant a''n rheolau sefydlog, sydd yn gosod allan sut mae''r corff yn gweithio, a dwi''n credu, gyda hwnna hefyd, byddwn i am glywed barn pob eraill ynglŷn â''n rheolau sefydlog ni, nid ein bod ni yn mynd ati i benderfynu, ''O, mae eisiau newid hwn, dyma beth rydyn ni''n mynd i''w wneud'', a dyna''i diwedd hi.', 'I mentioned governance arrangements and our standing orders, which set out how the body works, and I think that, with that also, we would want to hear other people''s views regarding our standing orders, not that we decide, ''Oh, this needs to be changed, this is what we''re going to do'', and that''s the end of it.', 'contribution 555110 · part 15/16', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC010-S0064', 'cym_n_for_eng:senedd-s4c-steve', 10, 64, 64, 'Rhodri Williams', 'Dwi''n credu y byddwn ni am ymgynghori''n ehangach ac edrych ar arfer da mewn llefydd eraill, os oes yna wersi y gallwn ni eu dysgu o lefydd eraill.', 'I think we would want to consult widely and look at good practice in other places, and to see if there are lessons that we can learn from other places.', 'contribution 555110 · part 16/16', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC011-S0065', 'cym_n_for_eng:senedd-s4c-steve', 11, 65, 65, 'Delyth Jewell', 'Diolch.', 'Thank you.', 'contribution 555176 · part 1/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC011-S0066', 'cym_n_for_eng:senedd-s4c-steve', 11, 66, 66, 'Delyth Jewell', 'Carolyn, cyn i ni ddod nôl, mae Llyr jest eisiau gofyn cwestiwn.', 'Carolyn, before we come back, Llyr just wants to ask a question.', 'contribution 555176 · part 2/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC012-S0067', 'cym_n_for_eng:senedd-s4c-steve', 12, 67, 67, 'Rhodri Williams', 'Yn sicr.', 'Certainly.', 'contribution 555179 · part 1/7', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC012-S0068', 'cym_n_for_eng:senedd-s4c-steve', 12, 68, 68, 'Rhodri Williams', 'Rydyn ni wedi siarad gyda BECTU—gyda''u cynrychiolydd llawnamser nhw yng Nghaerdydd, yn ogystal â''u cynrychiolydd nhw o fewn gweithlu S4C—ac maen nhw wedi bod yn hapus iawn i gydweithio â ni.', 'We have spoken to BECTU—with their full-time representative in Cardiff, as well as their representative within the S4C workforce—and they have been very happy to collaborate with us.', 'contribution 555179 · part 2/7', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC012-S0069', 'cym_n_for_eng:senedd-s4c-steve', 12, 69, 69, 'Rhodri Williams', 'Un o''r pethau cyntaf wnaethom ni pan gychwynnodd y broses yma—roedd Chris a finnau''n rhan o''r cyfarfod, gydag un aelod anweithredol arall o''r bwrdd—oedd siarad gyda BECTU ynglŷn â beth oedd angen ei wneud ar y cychwyn.', 'One of the first things we did when this process started—Chris and myself were involved in the meeting, with one other non-executive member of the board—was to speak to BECTU regarding what needed to be done at the outset.', 'contribution 555179 · part 3/7', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC012-S0070', 'cym_n_for_eng:senedd-s4c-steve', 12, 70, 70, 'Rhodri Williams', 'Ac wrth gwrs, yn y drafodaeth yna gyda BECTU, dyna lle y cytunom ni mai''r unig ffordd roedd y broses hon yn gallu gweithio''n effeithiol yw os oedd gyda ni mewn lle fecanwaith a oedd yn caniatáu i aelodau staff siarad heb fod yna ofn eu bod nhw''n mynd i ddioddef yn sgil y sylwadau y bydden nhw''n eu gwneud.', 'And of course, in that discussion with BECTU, that''s where we agreed that the only way in which this process could work effectively was if we had in place a mechanism that allowed staff members to speak openly without fear of consequences as a result of the comments that they would make.', 'contribution 555179 · part 4/7', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC012-S0071', 'cym_n_for_eng:senedd-s4c-steve', 12, 71, 71, 'Rhodri Williams', 'Felly, rydyn ni wedi cydweithredu â BECTU yn y gorffennol.', 'So, we have co-operated with BECTU in the past.', 'contribution 555179 · part 5/7', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC012-S0072', 'cym_n_for_eng:senedd-s4c-steve', 12, 72, 72, 'Rhodri Williams', 'Mae Carwyn Donovan, fel sy''n glir yn ei lythyr e atoch chi, Gadeirydd, yn ei gwneud hi''n amlwg bod yna awgrymiadau gan BECTU i''w gwneud ynglŷn â sut y gallwn ni gydweithio i sicrhau nad ydyn ni''n gweld y math hyn o broblemau''n codi eto.', 'Carwyn Donovan, as is clear in his letter to you, Chair, makes it clear that BECTU have suggestions to make as to how we can work together to ensure that we don''t see these kinds of problems arising again.', 'contribution 555179 · part 6/7', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC012-S0073', 'cym_n_for_eng:senedd-s4c-steve', 12, 73, 73, 'Rhodri Williams', 'Ac fe fyddwn ni''n bendant yn gwneud hynny wrth fynd ymlaen.', 'And we will most certainly be doing that in moving to the future.', 'contribution 555179 · part 7/7', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC013-S0074', 'cym_n_for_eng:senedd-s4c-steve', 13, 74, 74, 'Rhodri Williams', 'Dydy hi ddim mewn lle eto.', 'It''s not in place as of yet.', 'contribution 555207 · part 1/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC013-S0075', 'cym_n_for_eng:senedd-s4c-steve', 13, 75, 75, 'Rhodri Williams', 'Fel dwi''n dweud, bydd y bwrdd yn cyfarfod ymhen pythefnos, a''r bwriad bryd hynny fydd rhoi''r trefniadau perthnasol yn eu lle.', 'As I say, the board will meet in a fortnight''s time, and the intention at that time would be to put those arrangements in place.', 'contribution 555207 · part 2/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC014-S0076', 'cym_n_for_eng:senedd-s4c-steve', 14, 76, 76, 'Delyth Jewell', 'Diolch.', 'Thank you.', 'contribution 555210 · part 1/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC014-S0077', 'cym_n_for_eng:senedd-s4c-steve', 14, 77, 77, 'Delyth Jewell', 'Llyr.', 'Llyr.', 'contribution 555210 · part 2/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC015-S0078', 'cym_n_for_eng:senedd-s4c-steve', 15, 78, 78, 'Llyr Gruffydd', 'Diolch.', 'Thank you.', 'contribution 555211 · part 1/5', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC015-S0079', 'cym_n_for_eng:senedd-s4c-steve', 15, 79, 79, 'Llyr Gruffydd', 'Mae hi wedi bod yn ddefnyddiol iawn eich bod chi wedi sgopio mas y pedwar maes, os liciwch chi, neu''r themâu ble dŷch chi''n mynd i fod yn ffocysu arnyn nhw—arweinyddiaeth, diwylliant, polisïau a llywodraethiant.', 'It''s been very useful that you have scoped out those four areas, if you like, or the themes that you''ll be focusing on—leadership, culture, policies and governance.', 'contribution 555211 · part 2/5', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC015-S0080', 'cym_n_for_eng:senedd-s4c-steve', 15, 80, 80, 'Llyr Gruffydd', 'Wrth gwrs, wrth gyflwyno''r elfennau yna, pan roeddech chi''n sôn am arweinyddiaeth, fe wnaethoch chi gyfeirio at brif weithredwr ac efallai y cyfarwyddwyr gweithredol.', 'Of course, in presenting those elements, when you were talking about leadership, you referred to a chief executive and perhaps the executive directors.', 'contribution 555211 · part 3/5', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC015-S0081', 'cym_n_for_eng:senedd-s4c-steve', 15, 81, 81, 'Llyr Gruffydd', 'Ond wrth gwrs, mae gyda chi gyfrifoldeb arweinyddol hefyd yn y cyd-destun yna.', 'But of course, you have a leadership responsibility too in that context.', 'contribution 555211 · part 4/5', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC015-S0082', 'cym_n_for_eng:senedd-s4c-steve', 15, 82, 82, 'Llyr Gruffydd', 'Felly, pan roeddech chi''n dweud bod yna drafodaeth yn mynd i fod yn y bwrdd ar yr agweddau yma, ydych chi''n disgwyl fydd yna drafodaeth ynglŷn â''ch rôl chi fel cadeirydd?', 'So, when you said there was a discussion going to be in the board on these issues, do you expect there''ll be a discussion on your role as chair?', 'contribution 555211 · part 5/5', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC016-S0083', 'cym_n_for_eng:senedd-s4c-steve', 16, 83, 83, 'Rhodri Williams', 'Byddwn i''n disgwyl ein bod ni''n trafod ein rolau ni i gyd.', 'I would expect us to discuss all of our roles.', 'contribution 555123 · part 1/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC016-S0084', 'cym_n_for_eng:senedd-s4c-steve', 16, 84, 84, 'Rhodri Williams', 'Mae''n amlwg fod gan gadeirydd, fod gan fwrdd rôl bwysig mewn gosod safonau, mewn sicrhau fod safonau yn cael eu cadw atyn nhw, ac mewn arddangos y gwerthoedd a''r safonau rŷm ni am eu gweld o fewn y sefydliad yn y ffordd rŷm ni''n hunain yn gweithredu, ac i roi pwyslais ar y math o werthoedd rŷm ni''n disgwyl i''r corff weithredu yn gyson â nhw.', 'Clearly, a chair and a board have an important role in setting standards and ensuring that standards are adhered to, and in demonstrating those values and standards that we want to see within the organisation in the way that we ourselves conduct ourselves, and to place an emphasis on the kinds of values that we expect the organisation to act in accordance with.', 'contribution 555123 · part 2/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC017-S0085', 'cym_n_for_eng:senedd-s4c-steve', 17, 85, 85, 'Llyr Gruffydd', 'Achos yn y ffordd wnaethoch chi gyflwyno''r cyd-destun yna gynnau, roeddwn i jest yn teimlo bod yna awgrym, ac efallai roedd e i''w glywed ychydig ddoe yn y dystiolaeth hefyd, mai cyfrifoldeb eraill weithiau yw hyn ac mai pobl eraill sy''n gorfod delio efo''r pethau yma.', 'Because in the way that you presented that context earlier, I just felt that there was a suggestion, and perhaps it could be heard yesterday in the evidence, that this responsibility is for others and other people have to deal with this.', 'contribution 555127 · part 1/3', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC017-S0086', 'cym_n_for_eng:senedd-s4c-steve', 17, 86, 86, 'Llyr Gruffydd', 'Nawr, mae hynny yn wir i raddau—wrth gwrs ei fod e—ond ar ddiwedd y dydd, chi yw''r cadeirydd, ac atoch chi—dyna fyddai canfyddiad pobl, boed yn deg neu beidio—the buck stops there, yntefe?', 'Now, that is true to some extent—of course it is—but at the end of the day, you are the chair, and people''s perception would be, fair or not, that the buck stops there with you.', 'contribution 555127 · part 2/3', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC017-S0087', 'cym_n_for_eng:senedd-s4c-steve', 17, 87, 87, 'Llyr Gruffydd', 'Felly, sut fyddech chi''n disgrifio''ch perfformiad chi dros y cyfnod diwethaf yma?', 'How would you describe your performance over this last period?', 'contribution 555127 · part 3/3', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC018-S0088', 'cym_n_for_eng:senedd-s4c-steve', 18, 88, 88, 'Rhodri Williams', 'Gaf i ddweud gair i ddechrau ynglŷn â ble mae''r cyfrifoldeb?', 'If I could say a few words first of all on where responsibility lies.', 'contribution 555133 · part 1/10', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC018-S0089', 'cym_n_for_eng:senedd-s4c-steve', 18, 89, 89, 'Rhodri Williams', 'Wrth gwrs, ar ddiwedd y dydd, mae''r cyfrifoldeb yn gorffen gyda''r cadeirydd.', 'Of course, at the end of the day, the buck stops with the chair.', 'contribution 555133 · part 2/10', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC018-S0090', 'cym_n_for_eng:senedd-s4c-steve', 18, 90, 90, 'Rhodri Williams', 'Gaf i ddweud yn glir fan hyn mod i''n derbyn yn llwyr y cyfrifoldeb am y penderfyniadau sydd wedi cael eu gwneud gan y bwrdd, a''u bod nhw''n benderfyniadau unfrydol gan y bwrdd?', 'May I say quite clearly here that I fully accept responsibility for the decisions that have been made by the board, and that they were unanimous decisions by the board?', 'contribution 555133 · part 3/10', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC018-S0091', 'cym_n_for_eng:senedd-s4c-steve', 18, 91, 91, 'Rhodri Williams', 'Byddwn i ddim am awgrymu am eiliad fy mod i am redeg i ffwrdd.', 'I wouldn''t want to suggest for a second that I would turn my back on those responsibilities.', 'contribution 555133 · part 4/10', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC018-S0092', 'cym_n_for_eng:senedd-s4c-steve', 18, 92, 92, 'Rhodri Williams', 'Rwy''n gwbl dawel fy meddwl ein bod ni fel bwrdd wedi gwneud y penderfyniadau iawn ar yr adeg iawn.', 'I am quite convinced that we as a board had made the right decisions at the right time.', 'contribution 555133 · part 5/10', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC018-S0093', 'cym_n_for_eng:senedd-s4c-steve', 18, 93, 93, 'Rhodri Williams', 'Yn fwy pwysig—y peth allweddol bwysig i fi—dwi''n gwbwl hyderus ein bod ni wedi gwneud y peth iawn i''r unigolion hynny o fewn S4C, a rhai ohonyn nhw y tu allan, sydd wedi dioddef o dan yr arweinyddiaeth flaenorol.', 'More importantly—the crucial thing for me—I am entirely confident that we did the right thing for those individuals within S4C, and some outside S4C, who have suffered under the previous leadership.', 'contribution 555133 · part 6/10', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC018-S0094', 'cym_n_for_eng:senedd-s4c-steve', 18, 94, 94, 'Rhodri Williams', 'O ran wedyn sut mae''r cyfrifoldeb ffurfiol hwnnw yn rhannu, rŷm ni yna i osod y disgwyliadau.', 'In terms of how that formal responsibility is divided, we are there to set expectations.', 'contribution 555133 · part 7/10', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC018-S0095', 'cym_n_for_eng:senedd-s4c-steve', 18, 95, 95, 'Rhodri Williams', 'Mewn perthynas â pholisïau, y bwrdd sydd yn gyfrifol am y strategaeth, y weithrediaeth sydd yn gyfrifol am ei weithredu hi.', 'In relation to policies, the board is responsible for strategy, the executive is responsible for executing that strategy.', 'contribution 555133 · part 8/10', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC018-S0096', 'cym_n_for_eng:senedd-s4c-steve', 18, 96, 96, 'Rhodri Williams', 'Mae cytundeb y prif weithredwr yn dweud mai cyfrifoldeb y prif weithredwr yw sicrhau bod gan S4C amgylchedd gwaith lle mae pawb yn trin ei gilydd â pharch, a lle mae urddas a thegwch yn greiddiol i holl weithgareddau''r cwmni.', 'The contract of the chief executive says that it''s the responsibility of the chief executive to ensure that S4C has a working environment where everyone treats each other with respect, and where dignity and fairness are at the core of all of the company''s activities.', 'contribution 555133 · part 9/10', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC018-S0097', 'cym_n_for_eng:senedd-s4c-steve', 18, 97, 97, 'Rhodri Williams', 'Os rhowch chi''r paragraff yna ochr yn ochr ag adroddiad Capital Law, mae e''n glir nad oedd hynny yn digwydd.', 'If you place that paragraph alongside the Capital Law report, then it is clear that that was not happening.', 'contribution 555133 · part 10/10', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC019-S0098', 'cym_n_for_eng:senedd-s4c-steve', 19, 98, 98, 'Llyr Gruffydd', 'Ond a ydych chi''n siomedig eich bod chi ddim wedi pigo lan ar hynny ynghynt—dwi''n siŵr eich bod chi—ac yn cydnabod bod hynny efallai yn fethiant?', 'But are you disappointed that you hadn''t picked up on that earlier—I''m sure you are—and do you acknowledge that that perhaps is a failure?', 'contribution 555148 · part 1/1', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC020-S0099', 'cym_n_for_eng:senedd-s4c-steve', 20, 99, 99, 'Rhodri Williams', 'Yn sicr, dwi''n flin ein bod ni ddim wedi pigo lan arno fe''n gynt, ond dwi ddim yn credu fod yna fai ar bobl am beidio â sylweddoli hynny.', 'Certainly, I''m sorry that we didn''t pick up on it earlier, but I don''t think that you can place blame on people for not realising that.', 'contribution 555151 · part 1/8', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC020-S0100', 'cym_n_for_eng:senedd-s4c-steve', 20, 100, 100, 'Rhodri Williams', 'Oherwydd ysgrifennodd BECTU at y prif weithredwr yn gyntaf ar 2 Rhagfyr 2022, ac fe gynigiodd BECTU—yn yr un ffordd â maen nhw''n cynnig helpu yn y broses o wella pethau nawr—i''r prif weithredwr bryd hynny i gydweithio er mwyn delio gyda''r problemau.', 'Because BECTU wrote to the chief executive first of all on 2 December 2022, and BECTU—just as they have offered to help in the process of making improvements now—did offer the chief executive at that time that they would work with her to deal with the problems.', 'contribution 555151 · part 2/8', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC020-S0101', 'cym_n_for_eng:senedd-s4c-steve', 20, 101, 101, 'Rhodri Williams', 'Fe dderbynion ni fel bwrdd adroddiadau gan y prif weithredwr ynglŷn â''r broses honno.', 'We as a board received reports from the chief executive on that process.', 'contribution 555151 · part 3/8', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC020-S0102', 'cym_n_for_eng:senedd-s4c-steve', 20, 102, 102, 'Rhodri Williams', 'Fe dderbynion ni''r rheini drwy''r pwyllgor pobl a thaliadau sydd yn gyfrifol am faterion adnoddau dynol, ac fe dderbynion ni nhw yn uniongyrchol fel aelodau''r bwrdd.', 'We received those through the people and remuneration committee, which is responsible for HR issues, and we received them directly as members of the board.', 'contribution 555151 · part 4/8', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC020-S0103', 'cym_n_for_eng:senedd-s4c-steve', 20, 103, 103, 'Rhodri Williams', 'Yr hyn oedd yn cael ei ddweud wrthym ni oedd fod yna gamau yn cael eu rhoi mewn lle, ymarfer gwrando â''r staff, a fod popeth yn symud i''r cyfeiriad iawn.', 'What we were told was that steps were being put in place, that there was a listening exercise with staff, and that everything was moving in the right direction.', 'contribution 555151 · part 5/8', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC020-S0104', 'cym_n_for_eng:senedd-s4c-steve', 20, 104, 104, 'Rhodri Williams', 'Felly, ydw, dwi''n rhwystredig ein bod ni ddim wedi deall yn gynt beth oedd dyfnder y problemau a''r pryder oedd gan aelodau staff, ond ar y llaw arall, doedd yna ddim tystiolaeth.', 'So, yes, I am frustrated that we hadn''t understood the gravity of the problems earlier and the concerns that staff members had, but on the other hand, there was no evidence.', 'contribution 555151 · part 6/8', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC020-S0105', 'cym_n_for_eng:senedd-s4c-steve', 20, 105, 105, 'Rhodri Williams', 'Cawsom ni rywfaint o dystiolaeth pan roeddem ni''n cyfarfod yng Nghaernarfon ym mis Ionawr 2023 bod yna anesmwythyd, fel byddwn i''n ei ddisgrifio fe.', 'We received some evidence when we met in Caernarfon in January 2023 that there was some disquiet, as I would describe it.', 'contribution 555151 · part 7/8', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC020-S0106', 'cym_n_for_eng:senedd-s4c-steve', 20, 106, 106, 'Rhodri Williams', 'Ond fy nehongliad i o hwnna oedd bod staff S4C yng Nghaernarfon yn arbennig yn teimlo eu bod nhw yn cael eu diystyrru braidd, eu bod nhw allan ohoni, nid y math o gyhuddiadau difrifol a oedd yn cael eu codi gan BECTU maes o law.', 'But my interpretation of that was that S4C staff in Caernarfon particularly felt that they were being forgotten, that they were out of the picture, not the kind of serious allegations that were raised by BECTU later on.', 'contribution 555151 · part 8/8', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC021-S0107', 'cym_n_for_eng:senedd-s4c-steve', 21, 107, 107, 'Alun Davies', 'Dwi eisiau mynd nôl at hynny, os caf i, Rhodri.', 'I want to go back to that, if I may, Rhodri.', 'contribution 555221 · part 1/4', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC021-S0108', 'cym_n_for_eng:senedd-s4c-steve', 21, 108, 108, 'Alun Davies', 'Rhodri a Chris, mae''r ddau ohonoch chi wedi bod yn glir yn eich tystiolaeth y prynhawn yma mai''r tro cyntaf i chi glywed am y profiadau staff a''r problemau yn y sefydliad oedd ym mis Ebrill y llynedd.', 'Rhodri and Chris, both of you have been clear in your evidence this afternoon that the first time you heard about the staff experiences and the problems within the organisation was in April of last year.', 'contribution 555221 · part 2/4', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC021-S0109', 'cym_n_for_eng:senedd-s4c-steve', 21, 109, 109, 'Alun Davies', 'Dwi''n credu fy mod i''n cofio adroddiadau bod Gwyn Williams wedi trafod hyn gyda chi ym mis Mehefin 2022, a bod yna adroddiadau wedi bod i chi fel aelodau''r bwrdd bryd hynny.', 'I think that I remember reports that Gwyn Williams had discussed this with you in June 2022, and that there had been reports to you as members of the board at that time.', 'contribution 555221 · part 3/4', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC021-S0110', 'cym_n_for_eng:senedd-s4c-steve', 21, 110, 110, 'Alun Davies', 'Rydych chi''n gwenu, so ydw i wedi camddeall, efallai?', 'You''re smiling, so have I misunderstood, perhaps?', 'contribution 555221 · part 4/4', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC022-S0111', 'cym_n_for_eng:senedd-s4c-steve', 22, 111, 111, 'Rhodri Williams', 'Dwi''n trio gweithio mas yn fy mhen sut i ddelio â''r pwynt rŷch chi''n codi yn y ffordd briodol.', 'I am trying to work out in my head how to deal with the point that you''ve raised in an appropriate manner.', 'contribution 555226 · part 1/5', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC022-S0112', 'cym_n_for_eng:senedd-s4c-steve', 22, 112, 112, 'Rhodri Williams', 'Os dywedaf i fod yna broses yn ymwneud ag adnoddau dynol yn digwydd ar yr adeg honno, ac fe gyflwynwyd apêl ynglŷn â''r broses honno a gafodd ei glywed gan gadeirydd y pwyllgor pobl a thaliadau.', 'If I say that there was a process related to HR that was happening at that time, and an appeal was made in relation to that process, and it was heard by the chair of the people and remuneration committee.', 'contribution 555226 · part 2/5', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC022-S0113', 'cym_n_for_eng:senedd-s4c-steve', 22, 113, 113, 'Rhodri Williams', 'Gwrthodwyd yr apêl hwnnw.', 'That appeal was rejected.', 'contribution 555226 · part 3/5', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC022-S0114', 'cym_n_for_eng:senedd-s4c-steve', 22, 114, 114, 'Rhodri Williams', 'Dyna oedd yr unig ymwneud rwy''n ymwybodol ohono fe o''r adeg honno.', 'That was the only involvement that I am aware of from that time.', 'contribution 555226 · part 4/5', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC022-S0115', 'cym_n_for_eng:senedd-s4c-steve', 22, 115, 115, 'Rhodri Williams', 'Does gen i ddim cofnod—a does gan neb arall ohonom ni gofnod—o gwynion yn cael eu codi bryd hynny ynglŷn â''r diwylliant mewnol ac ymddygiad uwch-swyddogion.', 'I don''t have any record—none of us have a record—of any complaints being raised at that point in relation to the internal culture and the behaviour of senior officials.', 'contribution 555226 · part 5/5', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC023-S0116', 'cym_n_for_eng:senedd-s4c-steve', 23, 116, 116, 'Rhodri Williams', 'Dwi ddim yn credu cawson ni dystiolaeth o hynny tan i BECTU ysgrifennu aton ni.', 'I don''t believe that we had evidence of that until BECTU wrote to us.', 'contribution 555335 · part 1/8', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC023-S0117', 'cym_n_for_eng:senedd-s4c-steve', 23, 117, 117, 'Rhodri Williams', 'Yr agosaf ddaethon ni oedd, buaswn i''n dweud, o fewn yr wythnos neu efallai 10 diwrnod cyn i lythyr BECTU gyrraedd, fe wnes i''n sicr glywed gan nifer o unigolion sy''n gweithio o fewn y sector fod yna broblem, bod yna anesmwythyd, ond doedd dim o hwnna wedi''i adrodd i ni.', 'The closest we came was, I would say, within the week or 10 days prior to BECTU''s letter arriving, I certainly heard from a number of individuals working within the sector that there was a problem and that there was disquiet among staff, but none of that had been reported to us.', 'contribution 555335 · part 2/8', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC023-S0118', 'cym_n_for_eng:senedd-s4c-steve', 23, 118, 118, 'Rhodri Williams', 'Efallai, o dan drefn gwbl wahanol lle byddai pobl yn gweithio yn y swyddfa am bum diwrnod yr wythnos a lle byddai cyfarfodydd pwyllgorau, yn ogystal â chyfarfodydd y bwrdd, yn digwydd yn un o swyddfeydd S4C—efallai byddai yna fwy o gyfle am ryw sgyrsiau.', 'Now, perhaps, under a different system where people would be working in the office five days a week and where committee meetings, as well as board meetings, would be happening within one of S4C''s offices, there may be more opportunity for chats off the record.', 'contribution 555335 · part 3/8', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC023-S0119', 'cym_n_for_eng:senedd-s4c-steve', 23, 119, 119, 'Rhodri Williams', 'Yn sicr, roedd e''n rhywbeth roeddwn i''n gyfarwydd ag ef pan oeddwn i''n gweithio i Ofcom flynyddoedd yn ôl, lle byddem ni''n mynd i Lundain i''r pencadlys i weithio a byddem ni''n cwrdd â''r cadeirydd, prif weithredwr ac aelodau eraill y bwrdd, a bydden nhw''n siarad, ''Sut mae pethau''n mynd yng Nghymru''r dyddiau yma?''', 'It was certainly something that I was familiar with when I worked for Ofcom many years ago, where we would go to the headquarters in London to work and we would meet the chair, the chief executive and other members of the board, and we''d have chats.', 'contribution 555335 · part 4/8', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC023-S0120', 'cym_n_for_eng:senedd-s4c-steve', 23, 120, 120, 'Rhodri Williams', 'Byddech chi''n cael cyfle i wneud hwnna.', 'They''d ask, ''How are things going in Wales?'', and you''d have the opportunity to do that.', 'contribution 555335 · part 5/8', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC023-S0121', 'cym_n_for_eng:senedd-s4c-steve', 23, 121, 121, 'Rhodri Williams', 'Mae''r cyfleoedd i wneud hynny llawer iawn yn llai, ac efallai taw un o''r pethau sydd eisiau inni edrych arno ar gyfer y dyfodol yw a oes angen addasu''n trefniadau ni, fel ein bod ni''n creu mwy o gyfleoedd i rywun i ddod aton ni dros goffi a dweud, ''O, allaf i gael gair tawel ynglŷn â hyn?''', 'But the opportunities to do those things are much reduced now, and one of the things that we need to look at for the future, perhaps, is whether we need to adapt our arrangements, so that we create more opportunities for somebody to come to us over a cup of coffee and say, ''Can I have a quiet word about this?''', 'contribution 555335 · part 6/8', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC023-S0122', 'cym_n_for_eng:senedd-s4c-steve', 23, 122, 122, 'Rhodri Williams', 'Ond digwyddodd ddim o hynny tan inni—.', 'But that didn''t happen until we—.', 'contribution 555335 · part 7/8', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC023-S0123', 'cym_n_for_eng:senedd-s4c-steve', 23, 123, 123, 'Rhodri Williams', 'Ac os edrychwch chi ar lythyr BECTU, mae Carwyn Donovan yn defnyddio''r geiriau ''out of the blue'', felly doedd e, yn sicr, ddim yn disgwyl ein bod ni''n ymwybodol o''r problemau hynny.', 'And if you look at the BECTU letter, Carwyn Donovan uses the words ''out of the blue'', so he certainly didn''t expect us to be aware of these problems.', 'contribution 555335 · part 8/8', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC024-S0124', 'cym_n_for_eng:senedd-s4c-steve', 24, 124, 124, 'Alun Davies', 'Y broblem sydd gen i gyda hynny yw bod adroddiad Capital Law yn awgrymu ac yn dweud rhywbeth tra gwahanol.', 'The problem I have with that is that Capital Law''s report suggests and says something quite different.', 'contribution 555239 · part 1/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC024-S0125', 'cym_n_for_eng:senedd-s4c-steve', 24, 125, 125, 'Alun Davies', 'Gwnaf i ddarllen un rhan ohono fe i chi:', 'I''ll read one part of it to you:', 'contribution 555239 · part 2/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC025-S0126', 'cym_n_for_eng:senedd-s4c-steve', 25, 126, 126, 'Alun Davies', 'Dyna''r gweithlu oeddet ti yn gyfrifol amdano. A doeddech chi ddim yn gwybod dim amdano fe.', 'That''s the workforce you were responsible for, and you didn''t know anything about it.', 'contribution 555244 · part 1/1', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC026-S0127', 'cym_n_for_eng:senedd-s4c-steve', 26, 127, 127, 'Rhodri Williams', 'Nac oeddwn, a—', 'No, and—', 'contribution 555246 · part 1/1', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC027-S0128', 'cym_n_for_eng:senedd-s4c-steve', 27, 128, 128, 'Alun Davies', 'A dwi''n ffeindio hynny yn anghredadwy, dyna''r peth, achos dŷch chi''n rheolwr profiadol.', 'I find that quite incredible, because you are an experienced manager.', 'contribution 555326 · part 1/1', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC028-S0129', 'cym_n_for_eng:senedd-s4c-steve', 28, 129, 129, 'Rhodri Williams', 'Ond ddim yn gweithredu yn y cyd-destun yma fel rheolwr.', 'But not operating in this context as a manager.', 'contribution 555327 · part 1/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC028-S0130', 'cym_n_for_eng:senedd-s4c-steve', 28, 130, 130, 'Rhodri Williams', 'Hynny yw, byddwn i''n mynd i swyddfa—', 'In other words, I''d go to an office—', 'contribution 555327 · part 2/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC029-S0131', 'cym_n_for_eng:senedd-s4c-steve', 29, 131, 131, 'Alun Davies', 'Mae gennyt ti ddegawdau, Rhodri, o brofiad yn y maes yma.', 'You have decades of experience in this area, Rhodri.', 'contribution 555328 · part 1/3', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC029-S0132', 'cym_n_for_eng:senedd-s4c-steve', 29, 132, 132, 'Alun Davies', 'Degawdau o brofiad.', 'Decades of experience.', 'contribution 555328 · part 2/3', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC029-S0133', 'cym_n_for_eng:senedd-s4c-steve', 29, 133, 133, 'Alun Davies', 'Dŷch chi''n gadeirydd profiadol, a doeddech chi ddim yn gwybod, nes eich bod chi''n cael llythyr gan yr undeb, beth oedd yn digwydd yn y sefydliad lle roeddech chi yn gadeirydd. Wir?', 'You are an experienced chairperson, and you didn''t know until you received a letter from the union what was happening within the organisation where you were chair.', 'contribution 555328 · part 3/3', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC030-S0134', 'cym_n_for_eng:senedd-s4c-steve', 30, 134, 134, 'Rhodri Williams', 'Nac oeddwn. Doedd neb—', 'No. None of—', 'contribution 555330 · part 1/1', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC031-S0135', 'cym_n_for_eng:senedd-s4c-steve', 31, 135, 135, 'Alun Davies', 'Wir?', 'Really?', 'contribution 555332 · part 1/1', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC032-S0136', 'cym_n_for_eng:senedd-s4c-steve', 32, 136, 136, 'Rhodri Williams', '—ymhlith y staff wedi dod ataf i tan hynny.', '—the staff had approached me until that time.', 'contribution 555333 · part 1/7', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC032-S0137', 'cym_n_for_eng:senedd-s4c-steve', 32, 137, 137, 'Rhodri Williams', 'Ac mae rheswm am hynny, Alun.', 'And there''s a reason for that, Alun.', 'contribution 555333 · part 2/7', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC032-S0138', 'cym_n_for_eng:senedd-s4c-steve', 32, 138, 138, 'Rhodri Williams', 'Hynny yw, dwi''n credu ei fod e''n glir yn llythyr BECTU pam nad oedd hynny wedi digwydd.', 'I think it''s clear in the BECTU letter why that hadn''t happened.', 'contribution 555333 · part 3/7', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC032-S0139', 'cym_n_for_eng:senedd-s4c-steve', 32, 139, 139, 'Rhodri Williams', 'Y rheswm oedd e ddim wedi digwydd, bod neb wedi teimlo eu bod nhw''n gallu dod ataf i neu at aelod arall o''r bwrdd, oedd eu bod nhw ofn y prif weithredwr.', 'The reason it hadn''t happened was that nobody had felt that they could approach me or another member of the board because of fear of the chief executive.', 'contribution 555333 · part 4/7', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC032-S0140', 'cym_n_for_eng:senedd-s4c-steve', 32, 140, 140, 'Rhodri Williams', 'Roedd ymddygiad y prif weithredwr, ac, eto, mae e''n cael ei ddisgrifio’n glir iawn yn adroddiad Capital Law, onid yw e?', 'The behaviour of the chief executive and the conduct of the chief executive, and, again, it''s described very clearly in the Capital Law report, isn''t it?', 'contribution 555333 · part 5/7', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC032-S0141', 'cym_n_for_eng:senedd-s4c-steve', 32, 141, 141, 'Rhodri Williams', 'Roedd ymddygiad y prif weithredwr yn wrthdrawiadol, yn ddifrïol ac yn anystyriol.', 'The conduct and behaviour of the chief executive was full of conflict, abusive and didn''t take account of people''s needs.', 'contribution 555333 · part 6/7', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC032-S0142', 'cym_n_for_eng:senedd-s4c-steve', 32, 142, 142, 'Rhodri Williams', 'Roedd pobl ofn—', 'People were scared—', 'contribution 555333 · part 7/7', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC033-S0143', 'cym_n_for_eng:senedd-s4c-steve', 33, 143, 143, 'Delyth Jewell', 'Diolch.', 'Thank you.', 'contribution 555341 · part 1/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC033-S0144', 'cym_n_for_eng:senedd-s4c-steve', 33, 144, 144, 'Delyth Jewell', 'Byddwn i jest eisiau atgoffa pobl fod yna bobl, os dŷn ni yn eu trafod nhw, sydd ddim yma i ateb, felly buaswn i eisiau inni fod yn ffocysu ar lywodraethiant ac nid ar unigolion.', 'I''d just like to remind people that if we are discussing certain people, they''re not here to respond, so we''d like to focus on governance and not individuals.', 'contribution 555341 · part 2/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC034-S0145', 'cym_n_for_eng:senedd-s4c-steve', 34, 145, 145, 'Alun Davies', 'Ond y cwestiwn yw, Rhodri, chi oedd yn gyfrifol amdani hi a''i hymddygiad a''i gwaith hi.', 'But the question, Rhodri, is that you were responsible for her and her behaviour and her work.', 'contribution 555343 · part 1/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC034-S0146', 'cym_n_for_eng:senedd-s4c-steve', 34, 146, 146, 'Alun Davies', 'Chi oedd yn gyfrifol amdano fe.', 'You were responsible for it.', 'contribution 555343 · part 2/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC035-S0147', 'cym_n_for_eng:senedd-s4c-steve', 35, 147, 147, 'Rhodri Williams', 'Ond os nad yw rhywun yn ymwybodol—hynny yw, eto, yr hyn a ddywedwn i i hynny, Alun, yw unwaith y ffeindion ni mas ddifrifoldeb y cwynion yma, cynhaliwyd cyfarfod o''r bwrdd y diwrnod hwnnw.', 'But if one isn''t aware—that is, again, what I would say to that, Alun, is that once we learnt of the gravity of these complaints, a meeting of the board was held on that same day.', 'contribution 555344 · part 1/4', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC035-S0148', 'cym_n_for_eng:senedd-s4c-steve', 35, 148, 148, 'Rhodri Williams', 'Cytunwyd y diwrnod hwnnw y byddem ni yn sefydlu ymchwiliad allanol fel bod modd i bobl siarad—hynny yw, oherwydd bod y llythyr yn dweud mai''r rheswm doedd yna ddim cwynion wedi ymddangos oedd ofn, cytunwyd bod yn rhaid creu''r mecanwaith yma, gofod diogel, lle gallai pobl ddweud eu pryderon heb orfod poeni am agweddau pobl eraill.', 'We agreed that day that we would establish an external inquiry so that people could talk—that is, because the letter said that the reason that no complaints had been received was because of fear, we decided that we needed to create this mechanism, this safe space, where people could express their concerns without having to worry about other people''s attitudes.', 'contribution 555344 · part 2/4', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC035-S0149', 'cym_n_for_eng:senedd-s4c-steve', 35, 149, 149, 'Rhodri Williams', 'Fe weithredon ni''n gyflym iawn, wedyn, i roi''r broses honno yn ei lle.', 'We took action very swiftly after that to put that process in place.', 'contribution 555344 · part 3/4', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC035-S0150', 'cym_n_for_eng:senedd-s4c-steve', 35, 150, 150, 'Rhodri Williams', 'Roedd e''n ddydd Gwener arnon ni''n derbyn y llythyr, roedd dydd Llun yn ŵyl y banc, erbyn dydd Mawrth, roedd Capital Law wedi ei benodi.', 'It was Friday when we received the letter, the Monday was a bank holiday, by the Tuesday, Capital Law had been appointed.', 'contribution 555344 · part 4/4', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC036-S0151', 'cym_n_for_eng:senedd-s4c-steve', 36, 151, 151, 'Delyth Jewell', 'Diolch am hwnna.', 'Thank you for that.', 'contribution 555345 · part 1/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC036-S0152', 'cym_n_for_eng:senedd-s4c-steve', 36, 152, 152, 'Delyth Jewell', 'Mae Tom eisiau dod i mewn, ac wedyn gwnawn ni fynd nôl at Llyr.', 'Tom wants to come in, then we''ll go back to Llyr.', 'contribution 555345 · part 2/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC037-S0153', 'cym_n_for_eng:senedd-s4c-steve', 37, 153, 153, 'Rhodri Williams', 'Wel, mae yna brosesau yn eu lle.', 'Well, there are processes in place.', 'contribution 555350 · part 1/9', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC037-S0154', 'cym_n_for_eng:senedd-s4c-steve', 37, 154, 154, 'Rhodri Williams', 'Mae gan y bwrdd, fel ŷn ni''n disgrifio, bwyllgor sydd yn gyfrifol am y materion yma.', 'The board, as we''ve been describing, has a committee that''s responsible for these matters.', 'contribution 555350 · part 2/9', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC037-S0155', 'cym_n_for_eng:senedd-s4c-steve', 37, 155, 155, 'Rhodri Williams', 'Mae gyda ni swyddogion sydd yn rhan o dîm rheoli sydd yn adrodd yn gyson.', 'We have officials who are part of a management team that report regularly.', 'contribution 555350 · part 3/9', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC037-S0156', 'cym_n_for_eng:senedd-s4c-steve', 37, 156, 156, 'Rhodri Williams', 'Felly, er enghraifft, ar 22 Rhagfyr, fe dderbyniais i e-bost gan y prif weithredwr yn dweud bod yna gyfarfod wedi bod gyda BECTU, ei fod e wedi bod yn un llwyddiannus.', 'So, for example, on 22 December, I received an e-mail from the chief executive saying that a meeting had been held with BECTU, that it had been a successful one.', 'contribution 555350 · part 4/9', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC037-S0157', 'cym_n_for_eng:senedd-s4c-steve', 37, 157, 157, 'Rhodri Williams', 'Dechreuodd y cyfarfod wrth i Carwyn Donovan ddweud ei fod e''n reassured oherwydd cyflymder ein hymateb, a chytunwyd i weithio''n agosach gyda BECTU.', 'The meeting had begun with Carwyn Donovan saying he was reassured because of the speed of our response, and it was agreed to work closer with BECTU.', 'contribution 555350 · part 5/9', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC037-S0158', 'cym_n_for_eng:senedd-s4c-steve', 37, 158, 158, 'Rhodri Williams', 'Hynny yw, dwi''n credu ei fod yn rhesymol inni fod yn credu yr hyn oedd yn cael ei ddweud.', 'So, I think it is reasonable for us to believe what was being said.', 'contribution 555350 · part 6/9', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC037-S0159', 'cym_n_for_eng:senedd-s4c-steve', 37, 159, 159, 'Rhodri Williams', 'Nawr, mae''n bosibl bod yr asesiad hwnnw ddim cystal ag oedd e, ond o''r wybodaeth a oedd ar gael inni fel aelodau o''r bwrdd, dwi''n credu roedden ni''n wirioneddol feddwl bod yna gamau wedi cael eu rhoi mewn lle—roedd yr ymarfer gwrando yma wedi digwydd—a bod y problemau a oedd wedi cael eu hamlinellu ac wedi cael eu trafod gyda BECTU yn gwella.', 'Now, it''s possible that that assessment was not as good as it was, but from the information available to us as members of the board, I think we did really think that steps had been put in place—this listening exercise had happened—and that the problems that had been outlined and discussed with BECTU were improving.', 'contribution 555350 · part 7/9', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC037-S0160', 'cym_n_for_eng:senedd-s4c-steve', 37, 160, 160, 'Rhodri Williams', 'Doedd yna ddim rheswm inni feddwl nad oedd hynny’n wir, a dwi ddim yn siŵr pa ffynonellau eraill y gallem ni fynd—.', 'There was no reason for us to think that that wasn''t true, and I''m not sure what other sources we could have had—.', 'contribution 555350 · part 8/9', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC037-S0161', 'cym_n_for_eng:senedd-s4c-steve', 37, 161, 161, 'Rhodri Williams', 'Yn sicr, byddai aelodau staff wedi cael cyfle i siarad gyda fi, cael cyfle i siarad gydag aelodau eraill y bwrdd, ond os nad oedden nhw''n teimlo’n gyfforddus, os nad oedden nhw''n teimlo’n ddiogel yn codi’r problemau hynny, yna doedd e ddim yn bosibl, ac mae hynny''n dristwch mawr, oherwydd dwi''n credu, y pwynt sydd wedi cael ei wneud gan Alun, fod y staff wedi dioddef yn sylweddol yn ystod y misoedd hynny, ac mae hynny’n ofid mawr i fi yn bersonol ac fel cadeirydd y bwrdd.', 'Certainly, staff members would have had an opportunity to speak with me, to speak with other members of the board, but if they didn''t feel comfortable, if they didn''t feel safe in raising those issues, then it wasn''t possible, and that is the great sadness, because I think, the point that has been made by Alun, the staff had suffered significantly during those months, and that is of great concern to me personally and as chair of the board.', 'contribution 555350 · part 9/9', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC038-S0162', 'cym_n_for_eng:senedd-s4c-steve', 38, 162, 162, 'Rhodri Williams', 'A gaf i jest ddweud un peth?', 'Could I just say one other thing?', 'contribution 555354 · part 1/5', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC038-S0163', 'cym_n_for_eng:senedd-s4c-steve', 38, 163, 163, 'Rhodri Williams', 'O gymryd eich sylwadau chi i ystyriaeth, Cadeirydd, hynny yw, gaf i eich annog chi i edrych eto ar adroddiad Capital Law?', 'In taking your comments into account, Chair, may I encourage you to look again at the Capital Law report?', 'contribution 555354 · part 2/5', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC038-S0164', 'cym_n_for_eng:senedd-s4c-steve', 38, 164, 164, 'Rhodri Williams', 'Mae hwnna''n ei wneud yn glir pam nad oedd neb wedi siarad—roedden nhw ofn siarad.', 'That makes it clear why people hadn''t spoken out—they feared speaking out.', 'contribution 555354 · part 3/5', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC038-S0165', 'cym_n_for_eng:senedd-s4c-steve', 38, 165, 165, 'Rhodri Williams', 'Roedd yna ddiwylliant o greu ofn.', 'There was a culture of fear.', 'contribution 555354 · part 4/5', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC038-S0166', 'cym_n_for_eng:senedd-s4c-steve', 38, 166, 166, 'Rhodri Williams', 'Mae e''n dweud yn yr adroddiad fod hwnna wedi cael ei fynegi fel polisi bwriadol o greu ofn oherwydd taw dyna oedd ei angen er mwyn sicrhau newid diwylliannol.', 'It says in the report that that had been expressed as a deliberate policy of creating fear because that''s what was needed to secure culture change.', 'contribution 555354 · part 5/5', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC039-S0167', 'cym_n_for_eng:senedd-s4c-steve', 39, 167, 167, 'Rhodri Williams', 'Ie, ond allwn ni ddim creu yr hyder hwnnw os ydyn nhw''n byw mewn awyrgylch o ofn ac o fygythiad, sef beth oedden nhw.', 'Yes, but we can''t create that confidence if they live in a culture of fear and threat, which was the case.', 'contribution 555361 · part 1/5', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC039-S0168', 'cym_n_for_eng:senedd-s4c-steve', 39, 168, 168, 'Rhodri Williams', 'Hynny yw, roedd polisi chwythu''r chwiban—dwi ddim yn credu, efallai, taw dyna fyddai''r polisi y dylid fod wedi cael ei ddefnyddio.', 'I mean, there was a whistle-blowing policy—I don''t think that that''s necessarily the policy that should have been used.', 'contribution 555361 · part 2/5', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC039-S0169', 'cym_n_for_eng:senedd-s4c-steve', 39, 169, 169, 'Rhodri Williams', 'Mae yna bolisi parch yn y gweithle—gallai rhywun fod wedi codi cwestiynau ynglŷn â hynny, ei fod e ddim yn cael ei weithredu''n effeithiol—polisi disgyblaeth, polisi cwynion.', 'There''s a dignity at work policy—someone could have raised questions on that, that it wasn''t being implemented effectively. There''s a discipline policy, a complaints procedure.', 'contribution 555361 · part 3/5', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC039-S0170', 'cym_n_for_eng:senedd-s4c-steve', 39, 170, 170, 'Rhodri Williams', 'Peidiwch â meddwl fy mod i''n meddwl ei fod e i gyd yn berffaith—dwi ddim yn awgrymu hynny o gwbl—ond roedd y cyfleoedd hynny yn bod.', 'Don''t think that I think everything''s perfect—I''m not suggesting that for one moment—but those opportunities did exist.', 'contribution 555361 · part 4/5', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC039-S0171', 'cym_n_for_eng:senedd-s4c-steve', 39, 171, 171, 'Rhodri Williams', 'Ond yr hyn mae adroddiad Capital Law—yr hyn mae''r staff eu hunain yn ei ddweud yw eu bod nhw''n byw mewn ofn, a dyna pam—', 'But what the Capital Law report says—what the staff themselves say—is that they lived in fear, and that''s why—', 'contribution 555361 · part 5/5', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC040-S0172', 'cym_n_for_eng:senedd-s4c-steve', 40, 172, 172, 'Delyth Jewell', 'Dwi''n mynd i ddod at Alun am gwestiwn atodol yn gyflym, ond dwi''n ymwybodol mai dim ond 20 munud sydd ar ôl gennym ni.', 'I''m going go over to Alun for a supplementary question, but I''m aware that we only have 20 minutes left from the time allocated.', 'contribution 555363 · part 1/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC040-S0173', 'cym_n_for_eng:senedd-s4c-steve', 40, 173, 173, 'Delyth Jewell', 'A fyddai amser gyda chi, ar ôl 2 o''r gloch, i aros gyda ni am ryw chwarter awr ychwanegol, os oes angen?', 'Would you have time, after 2 o''clock, to stay with us for about an extra quarter of an hour, if required?', 'contribution 555363 · part 2/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC041-S0174', 'cym_n_for_eng:senedd-s4c-steve', 41, 174, 174, 'Rhodri Williams', 'Byddai, wrth gwrs.', 'Yes, of course.', 'contribution 555357 · part 1/1', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC042-S0175', 'cym_n_for_eng:senedd-s4c-steve', 42, 175, 175, 'Delyth Jewell', 'Diolch am hwnna.', 'Thank you for that.', 'contribution 555360 · part 1/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC042-S0176', 'cym_n_for_eng:senedd-s4c-steve', 42, 176, 176, 'Delyth Jewell', 'Ond, dwi dal yn ymwybodol o''r amser, felly, Alun, os allwch chi fod yn fyr.', 'But I''m still aware of time, so, Alun, if you could be brief.', 'contribution 555360 · part 2/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC043-S0177', 'cym_n_for_eng:senedd-s4c-steve', 43, 177, 177, 'Alun Davies', 'A dyna beth sy''n achosi pryder i fi.', 'And that''s what causes concern for me.', 'contribution 555362 · part 1/6', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC043-S0178', 'cym_n_for_eng:senedd-s4c-steve', 43, 178, 178, 'Alun Davies', 'Rydych chi wedi disgrifio—.', 'You''ve described—.', 'contribution 555362 · part 2/6', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC043-S0179', 'cym_n_for_eng:senedd-s4c-steve', 43, 179, 179, 'Alun Davies', 'A does neb, dwi ddim yn credu, yn gwadu eich tystiolaeth chi y prynhawn yma, Rhodri, amboutu''r awyrgylch yn S4C.', 'And I don''t think anyone denies your evidence this afternoon, Rhodri, about the atmosphere in S4C.', 'contribution 555362 · part 3/6', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC043-S0180', 'cym_n_for_eng:senedd-s4c-steve', 43, 180, 180, 'Alun Davies', 'Chi oedd y cadeirydd a doeddech chi ddim yn gwybod dim amdano fe.', 'You were the chair and you didn''t know anything about it.', 'contribution 555362 · part 4/6', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC043-S0181', 'cym_n_for_eng:senedd-s4c-steve', 43, 181, 181, 'Alun Davies', 'Ac mae''n rhaid i ni ofyn y cwestiwn wedyn: ble oeddech chi?', 'And we have to ask the question then: where were you?', 'contribution 555362 · part 5/6', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC043-S0182', 'cym_n_for_eng:senedd-s4c-steve', 43, 182, 182, 'Alun Davies', 'Ble oeddech chi pan oedd aelodau staff S4C yn teimlo''n rhy ofnus i siarad amboutu eu profiad nhw yn y gwaith a doedd y cadeirydd ddim yno?', 'Where were you when staff members at S4C felt too frightened to speak about their experiences in work and the chair wasn''t there?', 'contribution 555362 · part 6/6', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC044-S0183', 'cym_n_for_eng:senedd-s4c-steve', 44, 183, 183, 'Rhodri Williams', 'Wel, dyw e ddim yn fater fy mod i ddim yno—', 'Well, it''s not a matter of my not being there—', 'contribution 555371 · part 1/1', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC045-S0184', 'cym_n_for_eng:senedd-s4c-steve', 45, 184, 184, 'Alun Davies', 'Wel, ble oeddech chi?', 'Well, where were you?', 'contribution 555372 · part 1/4', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC045-S0185', 'cym_n_for_eng:senedd-s4c-steve', 45, 185, 185, 'Alun Davies', 'Pam nad oeddech chi''n sylweddoli?', 'Why didn''t you realise?', 'contribution 555372 · part 2/4', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC045-S0186', 'cym_n_for_eng:senedd-s4c-steve', 45, 186, 186, 'Alun Davies', 'Os oedd y sefyllfa mor wael â beth rydych chi wedi ei ddisgrifio i ni y prynhawn yma, pam doeddech chi ddim yn sylweddoli beth oedd yn digwydd yna?', 'If the situation was as bad as you''ve described to us this afternoon, why didn''t you realise what was happening?', 'contribution 555372 · part 3/4', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC045-S0187', 'cym_n_for_eng:senedd-s4c-steve', 45, 187, 187, 'Alun Davies', 'Dyna beth dwi ddim yn deall.', 'That''s what I don''t understand.', 'contribution 555372 · part 4/4', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC046-S0188', 'cym_n_for_eng:senedd-s4c-steve', 46, 188, 188, 'Rhodri Williams', 'Wel, achos byddai''n rhaid i rywun ddweud.', 'Well, because somebody would have to tell us.', 'contribution 555373 · part 1/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC046-S0189', 'cym_n_for_eng:senedd-s4c-steve', 46, 189, 189, 'Rhodri Williams', 'Nawr, dwi wedi—', 'Now, I''ve—', 'contribution 555373 · part 2/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC047-S0190', 'cym_n_for_eng:senedd-s4c-steve', 47, 190, 190, 'Alun Davies', 'Ond mae''n rhaid eich bod chi''n gwybod sut mae—.', 'Surely you would have known how—.', 'contribution 555374 · part 1/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC047-S0191', 'cym_n_for_eng:senedd-s4c-steve', 47, 191, 191, 'Alun Davies', 'Come on.', 'Come on.', 'contribution 555374 · part 2/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC048-S0192', 'cym_n_for_eng:senedd-s4c-steve', 48, 192, 192, 'Rhodri Williams', 'Dwi wedi treulio digon o amser yn ein lleoliadau ni yn Sgwâr Canolog, yn yr Egin, llai, mae''n rhaid dweud, yn swyddfa Caernarfon, ac yn ystod y cyfnod yna roedd yna gyfleoedd.', 'I''ve spent long enough in our offices in the Egin and in Central Square, less, I have to say, in the Caernarfon office, and during that time there were opportunities.', 'contribution 555376 · part 1/6', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC048-S0193', 'cym_n_for_eng:senedd-s4c-steve', 48, 193, 193, 'Rhodri Williams', 'Hynny yw, dwi''n adnabod llawer iawn o''r aelodau staff yn ddigon da ac wedi siarad â nhw yn anffurfiol y tu allan i gyfarfodydd, ond mynegodd neb—.', 'I know many of the staff well enough and have spoken to them informally, outside of meetings, but nobody expressed these concerns.', 'contribution 555376 · part 2/6', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC048-S0194', 'cym_n_for_eng:senedd-s4c-steve', 48, 194, 194, 'Rhodri Williams', 'Dim ond ar ôl i lythyr BECTU gyrraedd gwnaeth y llifddorau agor.', 'It was only after the BECTU letter arrived that the floodgates opened.', 'contribution 555376 · part 3/6', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC048-S0195', 'cym_n_for_eng:senedd-s4c-steve', 48, 195, 195, 'Rhodri Williams', 'Ar ôl hynny, fe dderbyniais i negeseuon testun, fe dderbyniais i alwadau ffôn, fe ges i gyfarfodydd wyneb yn wyneb gydag aelodau o staff.', 'After that point, I received text messages, I received phone calls, I had face-to-face meetings with members of staff.', 'contribution 555376 · part 4/6', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC048-S0196', 'cym_n_for_eng:senedd-s4c-steve', 48, 196, 196, 'Rhodri Williams', 'Ond dim ond—.', 'But it was only then—.', 'contribution 555376 · part 5/6', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC048-S0197', 'cym_n_for_eng:senedd-s4c-steve', 48, 197, 197, 'Rhodri Williams', 'Hynny yw, roedd y cyfle''n bodoli, roeddwn i yno cyn hynny, ond dim ond ar ôl i''r llythyr yna gyrraedd fe ges i''r adroddiadau hynny gan aelodau staff.', 'The opportunities existed, I was there before then, but it was only after that letter was received that I received those reports from members of staff.', 'contribution 555376 · part 6/6', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC049-S0198', 'cym_n_for_eng:senedd-s4c-steve', 49, 198, 198, 'Alun Davies', 'Ac fe gest ti''r adroddiadau gan aelodau staff yn uniongyrchol.', 'And you had reports from staff directly.', 'contribution 555377 · part 1/1', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
