INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC055-S0205', 'cym_n_for_eng:senedd-s4c-steve', 55, 205, 205, 'Llyr Gruffydd', 'Diolch.', 'Thank you.', 'contribution 555383 · part 1/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC055-S0206', 'cym_n_for_eng:senedd-s4c-steve', 55, 206, 206, 'Llyr Gruffydd', 'Sut wnaethoch chi fel cadeirydd, a sut wnaeth y bwrdd, efallai, ystyried effaith cyhoeddi''r adroddiad ar yr unigolion oedd yn cael eu henwi yn adroddiad Capital Law?', 'How did you, as chair, and how did the board, perhaps, consider the impact of publishing the report on the individuals named in Capital Law''s report?', 'contribution 555383 · part 2/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC056-S0207', 'cym_n_for_eng:senedd-s4c-steve', 56, 207, 207, 'Rhodri Williams', 'Wel, fel dywedais i ar y dechrau, y bobl sydd wedi cael eu heffeithio fwyaf gan yr holl broses yma yw staff S4C.', 'Well, as I said at the outset, the people who have been impacted most by this process are S4C staff.', 'contribution 555384 · part 1/1', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC057-S0208', 'cym_n_for_eng:senedd-s4c-steve', 57, 208, 208, 'Llyr Gruffydd', 'Dwi ddim yn gwadu hynny, ond nid dyna gwnes i ofyn.', 'I don''t deny that, but that wasn''t my question.', 'contribution 555385 · part 1/1', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC058-S0209', 'cym_n_for_eng:senedd-s4c-steve', 58, 209, 209, 'Rhodri Williams', 'Na, na, ond nhw oedd yn ganolog i''r holl broses.', 'No, no, but it was they who were central to the whole process.', 'contribution 555386 · part 1/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC058-S0210', 'cym_n_for_eng:senedd-s4c-steve', 58, 210, 210, 'Rhodri Williams', 'Hynny yw, y cwestiwn yma o greu gofod diogel, o sicrhau bod—', 'This question of creating a safe space, of ensuring that—', 'contribution 555386 · part 2/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC059-S0211', 'cym_n_for_eng:senedd-s4c-steve', 59, 211, 211, 'Llyr Gruffydd', 'Ie, dwi''n deall hynny i gyd.', 'Yes, I understand all of that.', 'contribution 555387 · part 1/1', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC060-S0212', 'cym_n_for_eng:senedd-s4c-steve', 60, 212, 212, 'Rhodri Williams', '—y sgyrsiau i gyd o gwmpas y staff.', '—all conversations centred on the staff.', 'contribution 555388 · part 1/11', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC060-S0213', 'cym_n_for_eng:senedd-s4c-steve', 60, 213, 213, 'Rhodri Williams', 'Fe ddywedon ni wrth y staff na fyddai pobl eraill yn cael gafael ar yr adroddiad cyn nhw.', 'Now, we told the staff that others would not see the report before they did.', 'contribution 555388 · part 2/11', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC060-S0214', 'cym_n_for_eng:senedd-s4c-steve', 60, 214, 214, 'Rhodri Williams', 'Dwi ddim yn credu ei bod hi''n rhesymol nac yn deg bod unrhyw un, beth bynnag yw''r cyfeiriad atyn nhw yn yr adroddiad, yn cael mynediad ato fe cyn bod y staff eu hunain yn ei weld e.', 'I don''t think it would have been reasonable or fair for anyone, whatever reference is made to them in the report, to have access to that report before the staff themselves saw it.', 'contribution 555388 · part 3/11', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC060-S0215', 'cym_n_for_eng:senedd-s4c-steve', 60, 215, 215, 'Rhodri Williams', 'Ac o ystyried yr hyn oedd yn digwydd, yr ymgyrch oedd yn digwydd yn y wasg yn fy erbyn i, yn erbyn y bwrdd, yn erbyn S4C, yn erbyn DCMS, yn erbyn yr Ysgrifennydd Gwladol, a fyddai''n gyfrifol i ni i roi''r adroddiad ymlaen llaw i bobl a fyddai â''r cyfle i wneud drwg ac i geisio ymhellach—roedd digon o ymdrech wedi cael ei wneud yn barod, ond i geisio ymhellach i danseilio cynnwys yr adroddiad?', 'And, given what was happening and the campaign that was going on in the press against me, against the board, against S4C, against DCMS, against the Secretary of State, would it have been responsible for us to provide that report beforehand to people who would have an opportunity to misuse it and to further—plenty of efforts had been made already, but to further attempt to undermine the content of the report?', 'contribution 555388 · part 4/11', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC060-S0216', 'cym_n_for_eng:senedd-s4c-steve', 60, 216, 216, 'Rhodri Williams', 'Hynny yw, mae hwnna wedi digwydd ers hynny.', 'That has happened since then.', 'contribution 555388 · part 5/11', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC060-S0217', 'cym_n_for_eng:senedd-s4c-steve', 60, 217, 217, 'Rhodri Williams', 'Mae''n cael ei wadu fod dim o hwn wedi digwydd.', 'It''s being denied that any of this happened.', 'contribution 555388 · part 6/11', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC060-S0218', 'cym_n_for_eng:senedd-s4c-steve', 60, 218, 218, 'Rhodri Williams', 'Er gwaethaf pwysau''r dystiolaeth rydyn ni wedi ei derbyn, mae''n cael ei awgrymu nad oes yna ddim gwirionedd yn hwn.', 'Despite the weight of evidence that we have received, it''s suggested that there is no truth in it at all.', 'contribution 555388 · part 7/11', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC060-S0219', 'cym_n_for_eng:senedd-s4c-steve', 60, 219, 219, 'Rhodri Williams', 'Wel, mae''r adroddiad yn dangos yn glir i ni fod y pryderon a fynegwyd gan BECTU wedi cael eu cynnal.', 'Well, the report demonstrates clearly to us that the concerns expressed by BECTU have been borne out.', 'contribution 555388 · part 8/11', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC060-S0220', 'cym_n_for_eng:senedd-s4c-steve', 60, 220, 220, 'Rhodri Williams', 'Hynny yw, roedd disgrifiad BECTU o''r diwylliant o ofn yn un cywir iawn.', 'That is, BECTU''s description of the culture of fear was very accurate indeed.', 'contribution 555388 · part 9/11', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC060-S0221', 'cym_n_for_eng:senedd-s4c-steve', 60, 221, 221, 'Rhodri Williams', 'Felly, does gen i ddim rheswm i feddwl ein bod ni wedi bod yn annheg i neb.', 'And therefore I have no reason to believe that we have treated anybody unfairly.', 'contribution 555388 · part 10/11', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC060-S0222', 'cym_n_for_eng:senedd-s4c-steve', 60, 222, 222, 'Rhodri Williams', 'I ddweud y gwir, byddai fe wedi bod yn gwbl annheg i''r staff pe bai nhw''n clywed bod pobol oedd bellach ddim yn gweithio i S4C wedi cael gweld yr adroddiad cyn nhw.', 'To be honest, it would have been entirely unfair for the staff if they''d heard that people who were no longer employed by S4C had seen the report before they had.', 'contribution 555388 · part 11/11', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC061-S0223', 'cym_n_for_eng:senedd-s4c-steve', 61, 223, 223, 'Llyr Gruffydd', 'Ond mae yna broses o hysbysu pobl ei fod e ar gael ei gyhoeddi, ddim o''r rheidrwydd rhannu copi.', 'But there is a process of informing people that it''s about to be published, not necessarily sharing a copy.', 'contribution 555251 · part 1/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC061-S0224', 'cym_n_for_eng:senedd-s4c-steve', 61, 224, 224, 'Llyr Gruffydd', 'Ydych chi''n meddwl ar lefel ddynol neu ar lefel foesol, neu o safbwynt cwrteisi, y dylai pobl gael rhyw fath o raghysbysiad bod rhywbeth yn cael ei gyhoeddi?', 'Do you think on a human level or on a moral level, or from a courtesy perspective, that people should have some sort of notice that it was about to be published?', 'contribution 555251 · part 2/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC062-S0225', 'cym_n_for_eng:senedd-s4c-steve', 62, 225, 225, 'Rhodri Williams', 'Ein ffocws ni oedd ar sicrhau bod y staff yn derbyn y wybodaeth cyn neb arall—', 'Our focus was on ensuring that the staff received the information before anybody else—', 'contribution 555252 · part 1/1', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC063-S0226', 'cym_n_for_eng:senedd-s4c-steve', 63, 226, 226, 'Llyr Gruffydd', 'Wel, ie, derbyn y wybodaeth, wrth gwrs.', 'Well, yes, of course, receiving the information.', 'contribution 555279 · part 1/1', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC064-S0227', 'cym_n_for_eng:senedd-s4c-steve', 64, 227, 227, 'Rhodri Williams', '—a dyna mae''n ffocws ni wedi bod trwy''r—.', '—and that''s what our focus has been throughout—.', 'contribution 555280 · part 1/5', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC064-S0228', 'cym_n_for_eng:senedd-s4c-steve', 64, 228, 228, 'Rhodri Williams', 'Ac oherwydd natur yr adroddiad, doedd e ddim yn hysbys.', 'And because of the nature of the report, it wasn''t known.', 'contribution 555280 · part 2/5', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC064-S0229', 'cym_n_for_eng:senedd-s4c-steve', 64, 229, 229, 'Rhodri Williams', 'Doedden ni ddim yn dweud ymlaen llaw, ''Mae hwn yn mynd i gael ei gyhoeddi ymhen wythnos neu fel arall''.', 'We didn''t say beforehand, ''This will be published in seven days'' time or whatever''.', 'contribution 555280 · part 3/5', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC064-S0230', 'cym_n_for_eng:senedd-s4c-steve', 64, 230, 230, 'Rhodri Williams', 'Roedd e''n dynn iawn rhwng yr amser roedden ni''n barod i gyhoeddi a''r broses yna o rannu''r adroddiad gyda''r staff ac esbonio iddyn nhw, a rhoi cyfle iddyn nhw holi cwestiynau i ni ynglŷn â beth fyddai''n digwydd nesaf.', 'It was very tight in terms of timescale between the time that we were ready to publish and that process of sharing the report with staff and explaining to them, and giving them an opportunity to ask us questions on the next steps.', 'contribution 555280 · part 4/5', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC064-S0231', 'cym_n_for_eng:senedd-s4c-steve', 64, 231, 231, 'Rhodri Williams', 'A does gen i ddim problemau ynglŷn â pheidio bod wedi''i rannu e gyda neb arall.', 'And I have no concerns about not having shared it with anybody else.', 'contribution 555280 · part 5/5', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC065-S0232', 'cym_n_for_eng:senedd-s4c-steve', 65, 232, 232, 'Llyr Gruffydd', 'Na, ond o ran hysbysu pobl fod adroddiad yn cael ei gyhoeddi, fyddech chi''n disgwyl bod rhywun sy''n cael ei enwi o leiaf yn cael cyfle 24 awr, neu ychydig oriau hyd yn oed, jest i baratoi''u hunain fod rhywbeth yn cael ei gyhoeddi sydd yn sôn amdanyn nhw.', 'No, but in terms of informing people that a report was about to be published, you would expect that somebody who''s named would at least have an opportunity, 24 hours or a few hours, just to prepare themselves that something was being published that talks about them.', 'contribution 555254 · part 1/3', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC065-S0233', 'cym_n_for_eng:senedd-s4c-steve', 65, 233, 233, 'Llyr Gruffydd', 'Hynny yw, dwi jest yn derbyn eich bod chi''n rhyw ddi-hid ac yn galon-galed iawn yn hynny o beth.', 'I''m just getting that you''re being somewhat rash and very hard-hearted in that regard.', 'contribution 555254 · part 2/3', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC065-S0234', 'cym_n_for_eng:senedd-s4c-steve', 65, 234, 234, 'Llyr Gruffydd', 'Dwi ddim yn sôn am rannu copi o''r adroddiad na dim byd, ond ar lefel cyfrifoldeb moesol i unigolion, dŷch chi ddim yn teimlo unrhyw fath o gyfrifoldeb yn hynny o beth?', 'I''m not talking about sharing a copy of the report, but in terms of a moral responsibility to individuals, don''t you feel any sort of responsibility in that regard?', 'contribution 555254 · part 3/3', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC066-S0235', 'cym_n_for_eng:senedd-s4c-steve', 66, 235, 235, 'Rhodri Williams', 'Dwi''n teimlo''r cyfrifoldeb moesol tuag at y staff.', 'I feel a moral responsibility towards the staff.', 'contribution 555257 · part 1/1', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC067-S0236', 'cym_n_for_eng:senedd-s4c-steve', 67, 236, 236, 'Llyr Gruffydd', 'Felly, unwaith mae rhywun yn gadael S4C, dyna fe wedyn, ie?', 'So, once somebody leaves S4C, that''s it, is it?', 'contribution 555258 · part 1/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC067-S0237', 'cym_n_for_eng:senedd-s4c-steve', 67, 237, 237, 'Llyr Gruffydd', 'Os ydyn nhw''n gyn-staff, chi ddim yn rhan o—?', 'If they''re former staff, you''re not part of—?', 'contribution 555258 · part 2/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC068-S0238', 'cym_n_for_eng:senedd-s4c-steve', 68, 238, 238, 'Rhodri Williams', 'Na, ni''n sôn fan hyn am bobl, am ddau unigolyn oedd wedi cael eu diswyddo, ac a oedd, fel dwi''n ei ddweud, yn cynnal ymgyrch cyhoeddus iawn, gan ddefnyddio—', 'No, we''re talking here about people, about two individuals who had been dismissed, and, as I''ve said, were waging a very public campaign, using—', 'contribution 555259 · part 1/1', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC069-S0239', 'cym_n_for_eng:senedd-s4c-steve', 69, 239, 239, 'Llyr Gruffydd', 'Wel, os ŷch chi eisiau ei fframio fe mewn modd o un garfan yn erbyn y llall, ond ŷch chi''n ddigon siarp i wybod byddai efallai peidio hysbysu rhywun o flaen llaw yn rhoi arf iddyn nhw ei dwlu yn ôl atoch chi, os dyna''r gêm ŷch chi''n ei chwarae.', 'Well, if you want to frame it as one group against another, but you''re sharp enough to know that perhaps not informing somebody beforehand would give them something to throw back at you, if that''s the game you''re playing.', 'contribution 555260 · part 1/1', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC070-S0240', 'cym_n_for_eng:senedd-s4c-steve', 70, 240, 240, 'Rhodri Williams', 'Wel, fe allaf i weld hynny, ond yn y trafodaethau rhyngom ni a''n tîm cyfreithiol, penderfynwyd peidio.', 'Well, I can understand that point, but in the discussions between ourselves and our legal team, the decision was taken not to do that.', 'contribution 555262 · part 1/1', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC071-S0241', 'cym_n_for_eng:senedd-s4c-steve', 71, 241, 241, 'Llyr Gruffydd', 'Diolch.', 'Thank you.', 'contribution 555287 · part 1/1', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC072-S0242', 'cym_n_for_eng:senedd-s4c-steve', 72, 242, 242, 'Delyth Jewell', 'Iawn.', 'Okay.', 'contribution 555264 · part 1/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC072-S0243', 'cym_n_for_eng:senedd-s4c-steve', 72, 243, 243, 'Delyth Jewell', 'Fe wnawn ni fynd at Alun.', 'We''ll go on to Alun Davies now.', 'contribution 555264 · part 2/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC073-S0244', 'cym_n_for_eng:senedd-s4c-steve', 73, 244, 244, 'Rhodri Williams', 'Wel, gaf i ddweud un gair pellach ynglŷn â hwnna?', 'If I could just say one other thing on that issue.', 'contribution 555086 · part 1/3', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC073-S0245', 'cym_n_for_eng:senedd-s4c-steve', 73, 245, 245, 'Rhodri Williams', 'Pan gododd—.', 'When—.', 'contribution 555086 · part 2/3', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC073-S0246', 'cym_n_for_eng:senedd-s4c-steve', 73, 246, 246, 'Rhodri Williams', 'Rŷn ni wedi trafod y materion hyn gyda swyddogion DCMS ers derbyn llythyr cyntaf BECTU—gwnes i eu gwneud nhw''n ymwybodol o hynny, ac rŷn ni''n siarad yn gyson.', 'We have discussed these issues with DCMS officials since the receipt of the first BECTU letter, and made them aware of that, and we do speak regularly.', 'contribution 555086 · part 3/3', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC074-S0247', 'cym_n_for_eng:senedd-s4c-steve', 74, 247, 247, 'Alun Davies', 'Ie, yn amlwg.', 'Yes, clearly.', 'contribution 555091 · part 1/1', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC075-S0248', 'cym_n_for_eng:senedd-s4c-steve', 75, 248, 248, 'Rhodri Williams', 'Ar fwy nag un achlysur yn ystod y cyfnod yma, dwi wedi gofyn i''r swyddog rŷn ni''n delio gyda fe a fyddai fe''n fuddiol i drefnu cyfarfod wyneb yn wyneb, neu yn rhithiol os ydy e''n dod i hynny, gyda''r Ysgrifennydd Gwladol, a''r ateb a gefais oedd nad oedd angen gwneud hynny, felly.', 'On more than one occasion during this period, I have asked the official that we deal with whether it would be beneficial to arrange a face-to-face meeting, or a virtual meeting if it came to that, with the Secretary of State, and the response I was given was that that was not necessary.', 'contribution 555092 · part 1/1', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC076-S0249', 'cym_n_for_eng:senedd-s4c-steve', 76, 249, 249, 'Alun Davies', 'Dwi''n ffeindio hynny''n hollol shocking—shocking.', 'I find that completely shocking—shocking.', 'contribution 555094 · part 1/5', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC076-S0250', 'cym_n_for_eng:senedd-s4c-steve', 76, 250, 250, 'Alun Davies', 'I rywun sydd actually yn credu dylai darlledu ddim cael ei ddatganoli, dyw hynny ddim yn rhywbeth buaswn i wedi eisiau ei glywed.', 'For someone who actually thinks that broadcasting shouldn''t be devolved, that isn''t something I would have wanted to hear.', 'contribution 555094 · part 2/5', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC076-S0251', 'cym_n_for_eng:senedd-s4c-steve', 76, 251, 251, 'Alun Davies', 'Mae''n adlewyrchu problemau mawr gan y DCMS, dwi''n meddwl.', 'It reflects great problems with the DCMS, I think.', 'contribution 555094 · part 3/5', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC076-S0252', 'cym_n_for_eng:senedd-s4c-steve', 76, 252, 252, 'Alun Davies', 'Ond roeddwn i''n mynd i ofyn cwestiwn arall i Chris, os caf i.', 'But I was going to ask another question to Chris, if I may.', 'contribution 555094 · part 4/5', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC076-S0253', 'cym_n_for_eng:senedd-s4c-steve', 76, 253, 253, 'Alun Davies', 'Yn ystod y trafodaethau dŷch chi wedi bod yn eu cael fel bwrdd ac fel non-execs yn ystod y cyfnod yma, a wnaethoch chi ofyn am gymorth neu gefnogaeth gan y DCMS, gan y BBC, neu gan Lywodraeth Cymru, o unrhyw un o''r cyrff llywodraethol, fel petai?', 'During the discussions that you''ve been having as a board and as non-execs during this period, did you ask for support from the DCMS, the BBC, or Welsh Government, from any one of those governmental organisations?', 'contribution 555094 · part 5/5', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC077-S0254', 'cym_n_for_eng:senedd-s4c-steve', 77, 254, 254, 'Rhodri Williams', 'Efallai ei fod e''n haws i fi ateb hwnna, ydy e, Chris?', 'Perhaps it would be easier for me to answer that, Chris.', 'contribution 555101 · part 1/1', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC078-S0255', 'cym_n_for_eng:senedd-s4c-steve', 78, 255, 255, 'Rhodri Williams', 'Hynny yw, fe drafodon ni gyda''r DCMS a gyda Llywodraeth Cymru i sicrhau eu bod nhw''n ymwybodol o''r materion proses, a liciwn i bwysleisio hynny: doedd yna ddim cwestiwn o rannu gyda nhw unrhyw ganfyddiadau neu beth fyddai''n dod allan o''r adroddiad, a fyddai hynny ddim wedi bod yn bosibl achos doeddem ni ddim yn gwybod tan fod y tîm o fewn Capital Law yn cyflwyno eu hadroddiad nhw i ni.', 'Well, we did have discussions with the DCMS and Welsh Government to ensure that they were aware of the procedural issues, and I''d like to emphasise that: there was no question of sharing any findings or the results of the report, and that wouldn''t have been possible because we didn''t know until the team within Capital Law presented their report to us.', 'contribution 555105 · part 1/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC078-S0256', 'cym_n_for_eng:senedd-s4c-steve', 78, 256, 256, 'Rhodri Williams', 'Ac, ar bob achlysur, yr ymateb—ac yn fwy pendant gan DCMS na gan neb arall—yr ateb oedd mai mater gweithredol i fwrdd S4C oedd hwn, ac nad eu lle nhw oedd cynghori.', 'And, on all occasions, the response—and more specifically from DCMS than anywhere else—was that this was an operational issue for the S4C board, and it wasn''t their place to advise.', 'contribution 555105 · part 2/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC079-S0257', 'cym_n_for_eng:senedd-s4c-steve', 79, 257, 257, 'Alun Davies', 'Ie, ie.', 'Yes, yes.', 'contribution 555111 · part 1/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC079-S0258', 'cym_n_for_eng:senedd-s4c-steve', 79, 258, 258, 'Alun Davies', 'Ond cwestiwn jest tipyn yn wahanol gyda phwyslais gwahanol oedd gen i i Chris: a oeddech chi wedi gofyn am gefnogaeth tra roeddech chi''n ystyried—achos dwi''n cymryd, fel non-execs, roeddech chi''n trafod ymhlith eich gilydd beth oedd yn digwydd, ac roedd yna adroddiadau yn y cyfryngau; mi fuasai fe''n od petaech chi ddim yn siarad gyda''ch gilydd—wedi gofyn am gefnogaeth allanol i''ch helpu chi ddelio gyda''r peth, y materion yma?', 'But I had a slightly different question, with a different emphasis, to Chris: had you asked for support while you were considering—because I take it, as non-execs, you were discussing amongst yourselves what was happening, and there were reports in the media; it would have been odd if you weren''t talking to each other—had you asked for external support to help you deal with these issues?', 'contribution 555111 · part 2/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC080-S0259', 'cym_n_for_eng:senedd-s4c-steve', 80, 259, 259, 'Alun Davies', 'Ocê.', 'Okay.', 'contribution 555307 · part 1/8', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC080-S0260', 'cym_n_for_eng:senedd-s4c-steve', 80, 260, 260, 'Alun Davies', 'Diolch am hynny.', 'Thank you for that.', 'contribution 555307 · part 2/8', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC080-S0261', 'cym_n_for_eng:senedd-s4c-steve', 80, 261, 261, 'Alun Davies', 'Rhodri, os caf fi jest bennu gyda hwn: mi fuasech chi wedi gweld adroddiadau gan y pwyllgor dethol ar ôl eich ymddangosiad ddoe.', 'Rhodri, if I could just end on this: you will have seen reports from the select committee after your appearance yesterday.', 'contribution 555307 · part 3/8', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC080-S0262', 'cym_n_for_eng:senedd-s4c-steve', 80, 262, 262, 'Alun Davies', 'Maen nhw wedi dweud bod angen arweinyddiaeth newydd ar S4C.', 'They have said there''s a need for new leadership at S4C.', 'contribution 555307 · part 4/8', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC080-S0263', 'cym_n_for_eng:senedd-s4c-steve', 80, 263, 263, 'Alun Davies', 'Pan ofynnodd, dwi''n credu, Steve Crabb, ichi os oeddech chi''n mynd i wneud cais am eich ailbenodi ym mis Ebrill, roeddech chi wedi rhoi ateb braidd yn od, i fy nghlustiau i, eich bod chi''n fodlon derbyn eich ailbenodi.', 'When, I think, Steve Crabb, asked you whether you were going to seek reappointment in April, you gave quite an odd answer, in my opinion, that you would be happy to accept reappointment.', 'contribution 555307 · part 5/8', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC080-S0264', 'cym_n_for_eng:senedd-s4c-steve', 80, 264, 264, 'Alun Davies', 'Doeddech chi ddim yn dweud eich bod chi''n mynd i wneud cais am hynny; roeddech chi''n dweud eich bod chi''n derbyn eich ailbenodi.', 'You didn''t say that you were going to apply for that; you said that you would be happy to accept a reappointment.', 'contribution 555307 · part 6/8', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC080-S0265', 'cym_n_for_eng:senedd-s4c-steve', 80, 265, 265, 'Alun Davies', 'Roeddwn i''n clywed hynny braidd yn od, y ffordd o eirio pethau.', 'I thought that was an odd way of wording things.', 'contribution 555307 · part 7/8', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC080-S0266', 'cym_n_for_eng:senedd-s4c-steve', 80, 266, 266, 'Alun Davies', 'Ond ydych chi wedi ystyried, dros nos, eich sefyllfa a ble dŷch chi''n sefyll heddiw ar ôl clywed barn y pwyllgor dethol?', 'Have you considered, overnight, your position and where you stand today after hearing the views of the select committee?', 'contribution 555307 · part 8/8', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC081-S0267', 'cym_n_for_eng:senedd-s4c-steve', 81, 267, 267, 'Rhodri Williams', 'Ydw, wrth gwrs dwi wedi, ac wedi trafod gydag eraill yr hyn ddigwyddodd ddoe.', 'Yes, of course, and I have discussed with others what happened yesterday.', 'contribution 555314 · part 1/11', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC081-S0268', 'cym_n_for_eng:senedd-s4c-steve', 81, 268, 268, 'Rhodri Williams', 'Yr hyn oedd yn fy synnu i ynglŷn â''n trafodaeth ni ddoe doedd ddim yr elfen dyw''r pwyllgor ddim yn awyddus i fi gael fy ailbenodi, ond y pwyslais i gyd ynglŷn â materion proses ac ynglŷn â diwedd y broses yma.', 'What surprised me in our discussion yesterday wasn''t this element that the committee wasn''t eager to see me reappointed, but the emphasis being solely on process and the end of this process.', 'contribution 555314 · part 2/11', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC081-S0269', 'cym_n_for_eng:senedd-s4c-steve', 81, 269, 269, 'Rhodri Williams', 'Doedd yna ddim ffocws o gwbl ddoe ar yr hyn mae aelodau staff S4C wedi''i ddioddef.', 'There was no focus whatsoever yesterday on what staff members in S4C have suffered.', 'contribution 555314 · part 3/11', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC081-S0270', 'cym_n_for_eng:senedd-s4c-steve', 81, 270, 270, 'Rhodri Williams', 'Doedd yna ddim unrhyw bryder yn cael ei fynegi ynglŷn â''r hyn maen nhw wedi gorfod ei ddioddef dros gyfnod hir o fisoedd.', 'There was no concern expressed about what they have had to go through over a long period of months.', 'contribution 555314 · part 4/11', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC081-S0271', 'cym_n_for_eng:senedd-s4c-steve', 81, 271, 271, 'Rhodri Williams', 'Fy mhryder i yw bod peth o—.', 'My concern is that—.', 'contribution 555314 · part 5/11', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC081-S0272', 'cym_n_for_eng:senedd-s4c-steve', 81, 272, 272, 'Rhodri Williams', 'Mae llawer o bobl wedi gwneud sylwadau ynglŷn â beth ddylai ddigwydd.', 'Many people have commented on what should happen.', 'contribution 555314 · part 6/11', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC081-S0273', 'cym_n_for_eng:senedd-s4c-steve', 81, 273, 273, 'Rhodri Williams', 'Dwi ddim yn amau eu cymhelliad nhw o gwbl, ond dyw unrhyw beth sydd yn creu ansefydlogrwydd pellach i''n staff ni ddim yn help i''r staff a dyw e ddim yn help i''r sefydliad yn ei gyfanrwydd.', 'I don''t doubt their motivation at all, but anything that creates further instability for our staff is not going to help the staff and it''s not going to help the organisation as a whole either.', 'contribution 555314 · part 7/11', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC081-S0274', 'cym_n_for_eng:senedd-s4c-steve', 81, 274, 274, 'Rhodri Williams', 'A dyna pam, pe bai''r Ysgrifennydd Gwladol yn gofyn—.', 'That''s why, if the Secretary of State were to ask me—.', 'contribution 555314 · part 8/11', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC081-S0275', 'cym_n_for_eng:senedd-s4c-steve', 81, 275, 275, 'Rhodri Williams', 'A dyna''r broses—hynny yw, does dim cwestiwn o wneud cais.', 'And that is the process—there''s no question of making an application.', 'contribution 555314 · part 9/11', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC081-S0276', 'cym_n_for_eng:senedd-s4c-steve', 81, 276, 276, 'Rhodri Williams', 'Does dim proses ymgeisio; mater i''r Ysgrifennydd Gwladol yw ailbenodi cadeirydd neu aelodau cyrff, ac mae e''n glir iawn hefyd yn y rheolau.', 'There is no application process, as such; it''s a matter for the Secretary of State to reappoint a chair or members of bodies, and it is very clear too in the rules and regulations.', 'contribution 555314 · part 10/11', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC081-S0277', 'cym_n_for_eng:senedd-s4c-steve', 81, 277, 277, 'Rhodri Williams', 'Ac fel roeddet ti''n ddigon caredig i gyfeirio ato''n gynt, dwi wedi bod o gwmpas digon hir i wybod na ddylid cymryd yn ganiataol byth, y bydd yna ailbenodiad yn digwydd, a dyna pam roeddwn i wedi defnyddio''r ffurf o eiriau fe wnes i.', 'And as you kindly referred to earlier, I''ve been around long enough to know that one should never take it for granted that there will be a reappointment, and that''s why I had used the wording that I did.', 'contribution 555314 · part 11/11', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC082-S0278', 'cym_n_for_eng:senedd-s4c-steve', 82, 278, 278, 'Alun Davies', 'Dwi''n deall hynny.', 'I understand that.', 'contribution 555315 · part 1/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC082-S0279', 'cym_n_for_eng:senedd-s4c-steve', 82, 279, 279, 'Alun Davies', 'Rhodri, gest ti dy arestio yn ymgyrchu dros S4C, do?', 'Rhodri, you were arrested in campaigning for S4C, weren''t you?', 'contribution 555315 · part 2/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC083-S0280', 'cym_n_for_eng:senedd-s4c-steve', 83, 280, 280, 'Rhodri Williams', 'Sawl gwaith.', 'A number of times.', 'contribution 555316 · part 1/1', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC084-S0281', 'cym_n_for_eng:senedd-s4c-steve', 84, 281, 281, 'Alun Davies', 'Sawl gwaith; dwi''n cofio.', 'A number of times.', 'contribution 555317 · part 1/7', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC084-S0282', 'cym_n_for_eng:senedd-s4c-steve', 84, 282, 282, 'Alun Davies', 'Ac mae dy ymrwymiad di i S4C wedi bod trwy dy fywyd di.', 'Your commitment to S4C has been lifelong.', 'contribution 555317 · part 2/7', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC084-S0283', 'cym_n_for_eng:senedd-s4c-steve', 84, 283, 283, 'Alun Davies', 'Dwi''n deall hynny a dwi ddim yn cwestiynu hynny o gwbl.', 'I understand that and I don''t question that.', 'contribution 555317 · part 3/7', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC084-S0284', 'cym_n_for_eng:senedd-s4c-steve', 84, 284, 284, 'Alun Davies', 'Mae''r issues dŷn ni wedi''u gweld dros y blynyddoedd diwethaf wedi bod yn anodd iawn, a dwi''n deall hynny.', 'But the issues we''ve seen over the last few years have been very difficult, and I understand that.', 'contribution 555317 · part 4/7', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC084-S0285', 'cym_n_for_eng:senedd-s4c-steve', 84, 285, 285, 'Alun Davies', 'Ond yr hyn sydd gen i yw, pan ŷch chi''n sôn am ddioddefaint aelodau staff S4C, ti oedd yn rhan o''r arweinyddiaeth wnaeth achosi hynny, ac mae''n rhaid, wedi hynny—.', 'But what I''m saying is, when you''re talking about the suffering of staff members at S4C, you were part of the leadership that caused that.', 'contribution 555317 · part 5/7', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC084-S0286', 'cym_n_for_eng:senedd-s4c-steve', 84, 286, 286, 'Alun Davies', 'Roeddech chi''n dweud yn gynt ''the buck stops''.', 'And you said earlier that ''the buck stops''.', 'contribution 555317 · part 6/7', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC084-S0287', 'cym_n_for_eng:senedd-s4c-steve', 84, 287, 287, 'Alun Davies', 'Nad ydych chi''n teimlo fel bod gyda chi gyfrifoldeb i ystyried pethau''n bellach?', 'Don''t you feel that you have a responsibility to consider things further?', 'contribution 555317 · part 7/7', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC085-S0288', 'cym_n_for_eng:senedd-s4c-steve', 85, 288, 288, 'Rhodri Williams', 'Mae yna wastad cyfrifoldeb ar gadeirydd neu aelod anweithredol o unrhyw gorff, wrth gwrs bod, ac mae hwnna yn barhaol o''r diwrnod cyntaf rŷch chi''n cael eich apwyntio hyd at ddiwedd eich cyfnod chi.', 'There is always a responsibility on a chair or a non-executive member of any body, of course that''s the case, and that is ongoing from the day of appointment up until the end of your period of service.', 'contribution 555318 · part 1/6', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC085-S0289', 'cym_n_for_eng:senedd-s4c-steve', 85, 289, 289, 'Rhodri Williams', 'Fel dywedais i ar y cychwyn, mae mhwyslais i a fy niddordeb i trwy''r holl broses yma a heddiw o hyd ar les y staff.', 'As I said at the outset, my emphasis and my interest through this whole process was and remains today on the well-being of the staff.', 'contribution 555318 · part 2/6', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC085-S0290', 'cym_n_for_eng:senedd-s4c-steve', 85, 290, 290, 'Rhodri Williams', 'Does yna ddim gair wedi dod ataf i fod unrhyw aelod o staff presennol S4C yn meddwl y byddai fe o les i S4C pe bawn i yn ymddiswyddo heddiw.', 'Not a word has been expressed to me that any member of the current S4C staff believes that it would be beneficial for S4C if I were to resign today.', 'contribution 555318 · part 3/6', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC085-S0291', 'cym_n_for_eng:senedd-s4c-steve', 85, 291, 291, 'Rhodri Williams', 'Does dim un o''r cwmnïau cynhyrchu dwi wedi ymwneud â nhw neu wedi trafod gyda nhw yn ystod y cyfnod yma yn awgrymu y byddai fe''n llesol.', 'Not one of the production companies that I''ve been involved with or have had discussions with during this period have suggested that it would be beneficial.', 'contribution 555318 · part 4/6', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC085-S0292', 'cym_n_for_eng:senedd-s4c-steve', 85, 292, 292, 'Rhodri Williams', 'I ddweud y gwir, mae''r neges yn glir iawn mai''r hyn maen nhw''n dymuno ei weld yn digwydd yw cyfnod o sefydlogi, a gadael i''r broses o wella sydd ar waith yn barod, fel gwnes i''n glir—.', 'To be honest, the message is quite clear that what they want to see happening is a period of stability, allowing the process of improvement, which is already in play, as I made clear earlier—.', 'contribution 555318 · part 5/6', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC085-S0293', 'cym_n_for_eng:senedd-s4c-steve', 85, 293, 293, 'Rhodri Williams', 'O fewn S4C, mae''r awyrgylch gwaith wedi gwella''n sylweddol ers ymadawiad dau o''r prif swyddogion, a''r hyn sydd ei angen yw sefydlogrwydd i adael i''r broses hynny barhau i weithio.', 'Within S4C, the working environment has improved significantly since the departure of two senior officials, and what we need now is stability to allow that process to continue to work.', 'contribution 555318 · part 6/6', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC086-S0294', 'cym_n_for_eng:senedd-s4c-steve', 86, 294, 294, 'Delyth Jewell', 'Ocê, diolch am hynna.', 'Okay, thank you for that.', 'contribution 555291 · part 1/4', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC086-S0295', 'cym_n_for_eng:senedd-s4c-steve', 86, 295, 295, 'Delyth Jewell', 'Fe wnawn ni symud, yn olaf, at Tom.', 'We''ll move finally to Tom.', 'contribution 555291 · part 2/4', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC086-S0296', 'cym_n_for_eng:senedd-s4c-steve', 86, 296, 296, 'Delyth Jewell', 'Ocê, fe wnawn ni fynd at Hefin a wedyn mynd at Tom.', 'Okay, we''ll go to Hefin and then Tom.', 'contribution 555291 · part 3/4', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC086-S0297', 'cym_n_for_eng:senedd-s4c-steve', 86, 297, 297, 'Delyth Jewell', 'Hefin.', 'Hefin.', 'contribution 555291 · part 4/4', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC087-S0298', 'cym_n_for_eng:senedd-s4c-steve', 87, 298, 298, 'Rhodri Williams', 'Yr hyn ddywedwn i yw bod anawsterau o''r math yma mewn cynifer o sefydliadau a chyrff yng Nghymru wedi bod yn llawer rhy gyffredin yn ystod y cyfnod diweddar yma.', 'What I would say is that difficulties of this kind in so many organisations and bodies in Wales have been too common during this recent period.', 'contribution 555293 · part 1/10', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC087-S0299', 'cym_n_for_eng:senedd-s4c-steve', 87, 299, 299, 'Rhodri Williams', 'Mae undeb rygbi ond yn un o''r cyrff sydd wedi delio gyda phroblemau gwahanol.', 'The rugby union is only one body that has dealt with different problems.', 'contribution 555293 · part 2/10', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC087-S0300', 'cym_n_for_eng:senedd-s4c-steve', 87, 300, 300, 'Rhodri Williams', 'Yr hyn ddywedwn i yw bod yr amgylchiadau ym mhob achos yn wahanol, a bod yr ymatebion bob amser yn wahanol.', 'What I would say is that the circumstances in every case are different, and that the responses have always been different.', 'contribution 555293 · part 3/10', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC087-S0301', 'cym_n_for_eng:senedd-s4c-steve', 87, 301, 301, 'Rhodri Williams', 'Dydw i ddim yn gwybod digon am sefyllfa yr undeb rygbi i wybod digon amdano fe i allu mynegi barn.', 'I don''t know enough about the situation in the rugby union to know enough about it to be able to provide a view.', 'contribution 555293 · part 4/10', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC087-S0302', 'cym_n_for_eng:senedd-s4c-steve', 87, 302, 302, 'Rhodri Williams', 'Mae''r hyn dwi wedi ei ddweud yn barod yn gosod allan fy marn i ynglŷn â S4C ac ynglŷn â''r hyn ddylai ddigwydd yn S4C, ac fy nghasgliad i ar hwnna yw fyddai i fi ymddiswyddo heddiw, neu ar unrhyw adeg arall cyn diwedd fy nhymor, ddim yn gwneud unrhyw les i S4C.', 'What I''ve said already sets out my views with regards to S4C and what should happen in S4C, and my conclusion in that regard would be that for me to resign today, or at any other time before the end of my term, would not be of any benefit to S4C.', 'contribution 555293 · part 5/10', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC087-S0303', 'cym_n_for_eng:senedd-s4c-steve', 87, 303, 303, 'Rhodri Williams', 'Gallaf ddychmygu y byddai fe''n gwneud i bobl eraill deimlo''n hapus ac yn hunanfodlon, ond, os siaradwch chi gyda''n staff ni neu gyda''n cyflenwyr, ein partneriaid ni, mae''r ymateb yn wahanol, ac mae rhai ohonyn nhw wedi mynegi hynny.', 'I can imagine that it would make other people feel happy and self-satisfied, but, if you speak to our staff or with our providers, our partners, the response is different, and some of them have expressed that.', 'contribution 555293 · part 6/10', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC087-S0304', 'cym_n_for_eng:senedd-s4c-steve', 87, 304, 304, 'Rhodri Williams', 'Roeddwn i''n gweld—.', 'I see that—.', 'contribution 555293 · part 7/10', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC087-S0305', 'cym_n_for_eng:senedd-s4c-steve', 87, 305, 305, 'Rhodri Williams', 'Mae yna lythyr gan un o''r cwmnïau cynhyrchu wedi dod at y pwyllgor yn mynegi''r farn yna.', 'There''s a letter from a production company that has been sent to the committee expressing that view.', 'contribution 555293 · part 8/10', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC087-S0306', 'cym_n_for_eng:senedd-s4c-steve', 87, 306, 306, 'Rhodri Williams', 'Roedd cadeirydd cwmni annibynnol mwyaf llwyddiannus Cymru ar y radio bore yma yn mynegi''r un farn.', 'The chair of one of the most successful independent television companies in Wales in a radio interview this morning expressed the same view.', 'contribution 555293 · part 9/10', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC087-S0307', 'cym_n_for_eng:senedd-s4c-steve', 87, 307, 307, 'Rhodri Williams', 'Felly, o dan yr amgylchiadau hynny, dwi''n gwbl dawel fy meddwl fy mod i yn gwneud y peth iawn.', 'Under those circumstances, I am completely at peace that I am doing the right thing.', 'contribution 555293 · part 10/10', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC088-S0308', 'cym_n_for_eng:senedd-s4c-steve', 88, 308, 308, 'Delyth Jewell', 'Ocê.', 'Okay.', 'contribution 555294 · part 1/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC088-S0309', 'cym_n_for_eng:senedd-s4c-steve', 88, 309, 309, 'Delyth Jewell', 'Fe wnawn ni symud at Tom.', 'We''ll move on to Tom.', 'contribution 555294 · part 2/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC089-S0310', 'cym_n_for_eng:senedd-s4c-steve', 89, 310, 310, 'Rhodri Williams', 'Fel roedd Chris yn awgrymu yn gynt, doedd y wybodaeth oedd yn dod atom ni ddim yn ddigon cyson a manwl i''n galluogi ni i weld fod yna anhawster fan hyn.', 'As Chris suggested earlier, the information provided to us wasn''t sufficiently consistent and detailed to allow us to identify any difficulties here.', 'contribution 555296 · part 1/6', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC089-S0311', 'cym_n_for_eng:senedd-s4c-steve', 89, 311, 311, 'Rhodri Williams', 'Rŷm ni wedi newid y drefn honno yn ystod cyfnod gwaith Capital Law, fel bod y dashfwrdd sydd nawr yn dod yn gyson—pedair gwaith y flwyddyn—at y pwyllgor pobl a thaliadau yn dangos hynny.', 'We have changed that system during the period in which Capital Law undertook their work, so that the dashboard that is now provided regularly—four times a year—to the people and remuneration committee does identify those patterns.', 'contribution 555296 · part 2/6', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC089-S0312', 'cym_n_for_eng:senedd-s4c-steve', 89, 312, 312, 'Rhodri Williams', 'A beth mae e''n dangos yw, yn ystod y flwyddyn 2023, fe wnaeth bron i ddwywaith gymaint o bobl adael S4C ag oedd wedi gwneud yn y ddwy flynedd cyn hynny.', 'And what it shows is that, during the year 2023, almost twice as many people left S4C than had done in the two years previous to that.', 'contribution 555296 · part 3/6', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC089-S0313', 'cym_n_for_eng:senedd-s4c-steve', 89, 313, 313, 'Rhodri Williams', 'Felly, mae yna gamau wedi''u cymryd yn barod.', 'So, steps have been taken already.', 'contribution 555296 · part 4/6', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC089-S0314', 'cym_n_for_eng:senedd-s4c-steve', 89, 314, 314, 'Rhodri Williams', 'Fe fyddwn i''n derbyn yn llwyr fod angen gwella''r prosesau hynny.', 'I would accept fully that we need to improve those processes.', 'contribution 555296 · part 5/6', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC089-S0315', 'cym_n_for_eng:senedd-s4c-steve', 89, 315, 315, 'Rhodri Williams', 'Yn yr yn ffordd ag y mae dashfwrdd gyda ni sydd yn dangos faint o bobl sydd yn defnyddio Clic, a faint sydd yn defnyddio iPlayer, dylem ni hefyd fod yn derbyn hwnnw.', 'Just as we have a dashboard that demonstrates how many people are using Clic, and how many people are using iPlayer, we should also be receiving that information.', 'contribution 555296 · part 6/6', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC090-S0316', 'cym_n_for_eng:senedd-s4c-steve', 90, 316, 316, 'Rhodri Williams', 'Wel, ddim routinely. Fe ddaeth e i''r golwg. Oherwydd bod y broses yma wedi cymryd cyfnod hir o amser rhwng diwedd mis Ebrill a mis Tachwedd, mi oedd yna drafodaeth fewnol ynglŷn â''r materion yma yn digwydd, ac fe benderfynwyd bod angen gwella arno fe, a hefyd, wrth gwrs, fe gynhaliwyd arolwg staff yn ystod y cyfnod hwnnw, ac roedd yr arolwg staff yn dweud wrthym ni''r hyn a oedd yn mynd i ymddangos maes o law yn adroddiad Capital Law—sef bod yna lefel uchel iawn o anfodlonrwydd gyda''r arweinyddiaeth.', 'Well, not routinely, no. It did emerge and because this process had taken a long period of time between the end of April and November, there was internal discussion on these issues that was ongoing, and a decision was taken that we needed to improve processes, and, of course, there was a staff survey conducted during that period, and that staff survey told us what would emerge in due time in the Capital Law report—that there was a high level of dissatisfaction with the leadership.', 'contribution 555299 · part 1/1', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC091-S0317', 'cym_n_for_eng:senedd-s4c-steve', 91, 317, 317, 'Rhodri Williams', 'Nac oedd. Dim cyn derbyn llythyr BECTU.', 'No, not until we received BECTU''s letter.', 'contribution 555301 · part 1/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC091-S0318', 'cym_n_for_eng:senedd-s4c-steve', 91, 318, 318, 'Rhodri Williams', 'Ar ôl llythyr BECTU—', 'Following BECTU''s letter—', 'contribution 555301 · part 2/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC092-S0319', 'cym_n_for_eng:senedd-s4c-steve', 92, 319, 319, 'Rhodri Williams', 'Mae''n amrywio dros gyfnod o amser.', 'It varies over a period of time.', 'contribution 555303 · part 1/7', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC092-S0320', 'cym_n_for_eng:senedd-s4c-steve', 92, 320, 320, 'Rhodri Williams', 'O ran absenoldeb o''r gwaith, fe oedd yna gynnydd yn ystod y cyfnod yma.', 'In terms of absences from work, there was an increase during this period.', 'contribution 555303 · part 2/7', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC092-S0321', 'cym_n_for_eng:senedd-s4c-steve', 92, 321, 321, 'Rhodri Williams', 'Hynny yw, gallaf i ddim, off top fy mhen, ddweud a oedd hwnna wedi dechrau yn 2023 cyn Ebrill, neu oedd e o Ebrill ymlaen.', 'I can''t, off the top of my head, say whether that had started in 2023, before April, or whether it was from April onwards.', 'contribution 555303 · part 3/7', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC092-S0322', 'cym_n_for_eng:senedd-s4c-steve', 92, 322, 322, 'Rhodri Williams', 'A dyna pam oedd rhaid gwneud yn siŵr bod gwell data gyda ni, a''i fod e''n dod aton ni yn fwy cyson.', 'And that''s why we had to make sure we had better data, and that we received it more regularly.', 'contribution 555303 · part 4/7', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC092-S0323', 'cym_n_for_eng:senedd-s4c-steve', 92, 323, 323, 'Rhodri Williams', 'Mae''n rhywbeth sydd wedi bod yn destun trafodaeth yn y bwrdd, i sicrhau bod y matrix yna o fesuriadau o''r math yna ar gael, a''u bod nhw''n ar gael yn gyson.', 'It''s something that''s been a topic of discussion in the board, to ensure that that matrix of measurements is available, and that they are available regularly.', 'contribution 555303 · part 5/7', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC092-S0324', 'cym_n_for_eng:senedd-s4c-steve', 92, 324, 324, 'Rhodri Williams', 'Dwi''n credu taw dyna yw''r pwynt—mae''n rhaid eu cael nhw yn ddigon cyson i weld ydy''r newidiadau yn arwyddocaol.', 'I think that is the point—you have to have them regularly enough to see whether the changes are significant.', 'contribution 555303 · part 6/7', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC092-S0325', 'cym_n_for_eng:senedd-s4c-steve', 92, 325, 325, 'Rhodri Williams', 'Ond, eto, doedd yna ddim byd cyn i lythyr BECTU gyrraedd a oedd yn gwneud inni feddwl bod yna rywbeth o''i le.', 'But, again, there was nothing before BECTU''s letter arrived that made us feel that there was something wrong.', 'contribution 555303 · part 7/7', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC093-S0326', 'cym_n_for_eng:senedd-s4c-steve', 93, 326, 326, 'Rhodri Williams', 'Wel, doedd e ddim yn un digon da, yn sicr, achos pe bai e, fe fyddem ni wedi bod yn ymwybodol, ''Mae yna rywbeth o''i le fan hyn.''', 'Well, it wasn''t good enough, certainly, because if it was, we would have been aware that there was something wrong here.', 'contribution 555305 · part 1/3', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC093-S0327', 'cym_n_for_eng:senedd-s4c-steve', 93, 327, 327, 'Rhodri Williams', 'Ond doedd e ddim, a dyna pam fe''i newidiwyd e.', 'But it wasn''t, and that''s why it has been changed.', 'contribution 555305 · part 2/3', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC093-S0328', 'cym_n_for_eng:senedd-s4c-steve', 93, 328, 328, 'Rhodri Williams', 'Mae yna drefn newydd yn ei le nawr sydd yn rhoi''r wybodaeth honno.', 'That''s why there is a new process in place now that does provide that information.', 'contribution 555305 · part 3/3', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC094-S0329', 'cym_n_for_eng:senedd-s4c-steve', 94, 329, 329, 'Rhodri Williams', 'Yr un peth y byddwn i yn ei ddweud yw nad dim ond gan un ffynhonnell roedden ni''n clywed bod yna welliannau ar waith, neu fod y cwynion a oedd wedi cael eu cyflwyno gan BECTU yn cael eu delio â nhw, a bod pethau yn gwella.', 'The one thing that I would say is that we weren''t hearing from one source only that improvements were happening, or that the complaints that had been presented by BECTU were being dealt with, and that things were improving.', 'contribution 555309 · part 1/4', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC094-S0330', 'cym_n_for_eng:senedd-s4c-steve', 94, 330, 330, 'Rhodri Williams', 'Nid dim ond y prif weithredwr a oedd yn dweud hynny; mae yna gyfarwyddwr adnoddau dynol, mae yna aelodau eraill o''r tîm rheoli.', 'It wasn''t just the chief executive that was saying that, but there''s an human resources director, and there are other members of the management team.', 'contribution 555309 · part 2/4', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC094-S0331', 'cym_n_for_eng:senedd-s4c-steve', 94, 331, 331, 'Rhodri Williams', 'Felly, nid dim ond o un ffynhonnell oedd e''n dod.', 'So, it wasn''t just coming from one source.', 'contribution 555309 · part 3/4', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC094-S0332', 'cym_n_for_eng:senedd-s4c-steve', 94, 332, 332, 'Rhodri Williams', 'Ond fel dwi''n dweud, hynny yw, byddwn i wedi bod wrth fy modd pe baem ni wedi cael rhyw fath o early warning system a fyddai''n caniatáu inni ddweud, ''Mae eisiau i ni wneud mwy'', ond doedd yna ddim.', 'But as I say, I would have been delighted if we''d had some early warning system that would allow us to say, ''We need to do more'', but there wasn''t one.', 'contribution 555309 · part 4/4', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC095-S0333', 'cym_n_for_eng:senedd-s4c-steve', 95, 333, 333, 'Rhodri Williams', 'Na, dwi ddim yn credu oedd gan—.', 'No, I don''t think—.', 'contribution 555208 · part 1/5', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC095-S0334', 'cym_n_for_eng:senedd-s4c-steve', 95, 334, 334, 'Rhodri Williams', 'Roedd yna nifer o wendidau, dwi''n credu, a ddaeth allan yn ystod ein trafodaethau, a ddaeth i''r golwg.', 'There were a number of weaknesses, I think, that came out during our discussions.', 'contribution 555208 · part 2/5', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC095-S0335', 'cym_n_for_eng:senedd-s4c-steve', 95, 335, 335, 'Rhodri Williams', 'Un oedd lefel isel iawn o asesu perfformiad staff.', 'One was a very low level of performance assessment with staff.', 'contribution 555208 · part 3/5', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC095-S0336', 'cym_n_for_eng:senedd-s4c-steve', 95, 336, 336, 'Rhodri Williams', 'Yn ystod y flwyddyn ddiwethaf, gwnaeth perfformiad aelodau''r tîm rheoli ddim cael ei asesu.', 'During the last year, the performance of the management team wasn''t assessed.', 'contribution 555208 · part 4/5', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC095-S0337', 'cym_n_for_eng:senedd-s4c-steve', 95, 337, 337, 'Rhodri Williams', 'Gwnaeth dim un ohonyn nhw gael eu hasesu am dros flwyddyn.', 'None of them was assessed for over a year.', 'contribution 555208 · part 5/5', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC096-S0338', 'cym_n_for_eng:senedd-s4c-steve', 96, 338, 338, 'Rhodri Williams', 'Wel, nid gyda chadeirydd nac aelod o''r bwrdd fyddai cyfweliadau yn digwydd wrth i bobl adael.', 'Well, those interviews wouldn''t happen with the chair or members of the board as people leave.', 'contribution 555216 · part 1/1', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC097-S0339', 'cym_n_for_eng:senedd-s4c-steve', 97, 339, 339, 'Rhodri Williams', 'Na, dyw hwnna ddim yn wir, fel mae''n digwydd.', 'Well, no. That''s not the case, as it happens.', 'contribution 555222 · part 1/1', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC098-S0340', 'cym_n_for_eng:senedd-s4c-steve', 98, 340, 340, 'Rhodri Williams', 'Wel, digwyddodd e ddim yn yr achos yma, ac, eto, dwi''n adnabod yn bersonol rai aelodau o''r staff oedd wedi gadael yn ystod y cyfnod.', 'Well, it didn''t happen in this case, and, again, I know personally some of the staff members who did leave during that period.', 'contribution 555225 · part 1/11', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC098-S0341', 'cym_n_for_eng:senedd-s4c-steve', 98, 341, 341, 'Rhodri Williams', 'Fe wnaethon nhw roi tystiolaeth i dîm Capital Law, ond gwnaethon nhw ddim mynegi''r amheuon hynny wrth iddyn nhw adael.', 'They did provide evidence to the Capital Law team, but they did not express those concerns when leaving.', 'contribution 555225 · part 2/11', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC098-S0342', 'cym_n_for_eng:senedd-s4c-steve', 98, 342, 342, 'Rhodri Williams', 'Ac, wrth gwrs, un o''r pethau—. Ac eto, a gaf i eich cyfeirio chi yn ôl at yr adroddiad, fe welwch chi sylwadau gan y prif weithredwr am faint o bobl oedd hi''n dymuno gweld yn gadael y corff.', 'And, of course, and, again, may I refer you back to the report, you will see comments from the chief executive on the number of people she wished to see leave the organisation.', 'contribution 555225 · part 3/11', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC098-S0343', 'cym_n_for_eng:senedd-s4c-steve', 98, 343, 343, 'Rhodri Williams', 'Dwi''n credu bod e''n cael ei ddweud bod yna hanner cant o staff y byddem ni yn well off yn eu colli nhw.', 'I think it said that there were 50 staff that we''d be better off without.', 'contribution 555225 · part 4/11', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC098-S0344', 'cym_n_for_eng:senedd-s4c-steve', 98, 344, 344, 'Rhodri Williams', 'Felly, roedd yna ymdrech fwriadol, fan hyn, yn cael ei wneud i gael gwared ar aelodau staff. Nawr, doedd hynny ddim yn rhywbeth ddaeth i''m sylw i tan yr adroddiad ei hunan.', 'So, there was a deliberate attempt here made to see staff leave and that wasn''t something that came to my attention until the report itself was received.', 'contribution 555225 · part 5/11', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC098-S0345', 'cym_n_for_eng:senedd-s4c-steve', 98, 345, 345, 'Rhodri Williams', 'Ac a gaf i ddweud hefyd, wrth gwrs, mae cyfnod o newid—pan ŷch chi''n newid beth mae''r corff yn ei wneud, sut mae e''n gweithredu, mae e''n naturiol i newid staff, i ddod â gwaed newydd i mewn ac i weld rhai pobl yn gadael.', 'And may I also say that, of course, any period of change—when you change how an organisation operates, then it''s natural that there will be some churn in staff, that new blood will come in and that some staff will leave.', 'contribution 555225 · part 6/11', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC098-S0346', 'cym_n_for_eng:senedd-s4c-steve', 98, 346, 346, 'Rhodri Williams', 'Mae hwnna—.', 'There is nothing inherently wrong with that.', 'contribution 555225 · part 7/11', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC098-S0347', 'cym_n_for_eng:senedd-s4c-steve', 98, 347, 347, 'Rhodri Williams', 'Does dim byd o''i le gyda hynny mewn egwyddor.', 'But there is a way of doing that, and that''s what all this is about, I think.', 'contribution 555225 · part 8/11', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC098-S0348', 'cym_n_for_eng:senedd-s4c-steve', 98, 348, 348, 'Rhodri Williams', 'Ond mae yna ffordd, a dyna beth mae hwn i gyd o gwmpas, dwi''n credu—y ffordd o wneud pethau.', 'It''s the way of doing things.', 'contribution 555225 · part 9/11', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC098-S0349', 'cym_n_for_eng:senedd-s4c-steve', 98, 349, 349, 'Rhodri Williams', 'Digwydd bod, dwi''n eistedd ar fwrdd y Cyngor y Defnyddwyr Dŵr—yn ystod y tair blynedd diwethaf mae e wedi cael prif weithredwr newydd, sydd wedi arwain proses o newid mewnol, ond wedi gwneud hynny drwy fynd â''r staff gyda hi, drwy sicrhau bod perfformiad staff y Cyngor Defnyddwyr Dŵr, yn eu harolygon staff nhw, bron yn afresymol o uchel, oherwydd bod y ffocws wedi bod ar les, iechyd ac ar fod yn ofalus o staff.', 'As it happens, I sit on the board of the Consumer Council for Water, and during the past three years, they''ve had a new chief executive, and they have led a process of internal change, but they''ve done so by taking the staff with them, by ensuring that the performance of the staff of the water consumer council, in their staff surveys, are almost irrationally high, because the focus has been entirely on the health, well-being and care of staff.', 'contribution 555225 · part 10/11', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC098-S0350', 'cym_n_for_eng:senedd-s4c-steve', 98, 350, 350, 'Rhodri Williams', 'Nid dyna ddigwyddodd gyda ni.', 'But that''s not what happened with us.', 'contribution 555225 · part 11/11', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC099-S0351', 'cym_n_for_eng:senedd-s4c-steve', 99, 351, 351, 'Rhodri Williams', 'Reit, oherwydd, yn syml iawn, yr amgylchiadau wnaeth arwain at ddiswyddo''r prif swyddog cynnwys, oedd ar ddydd Sadwrn yn Nantes, yn dilyn gêm rygbi.', 'Because, quite simply, the circumstances that led to the dismissal of the chief content officer occurred on a Saturday in Nantes, following a rugby match.', 'contribution 555245 · part 1/11', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC099-S0352', 'cym_n_for_eng:senedd-s4c-steve', 99, 352, 352, 'Rhodri Williams', 'Roedd y prif weithredwr yn bresennol yn yr un cyfarfodydd—nid cyfarfodydd yw''r gair iawn—yn yr un lleoliadau lle ddigwyddodd y digwyddiadau a arweiniodd at y penderfyniad.', 'The chief executive had attended the same meetings—well, they weren''t meetings—but the chief executive was present at the same locations where these events took place, which led to that decision.', 'contribution 555245 · part 2/11', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC099-S0353', 'cym_n_for_eng:senedd-s4c-steve', 99, 353, 353, 'Rhodri Williams', 'Felly, roedd gan y prif weithredwr ddiddordeb yn y mater.', 'So, the chief executive had an interest in that issue.', 'contribution 555245 · part 3/11', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC099-S0354', 'cym_n_for_eng:senedd-s4c-steve', 99, 354, 354, 'Rhodri Williams', 'Doedd hi ddim wedi rhannu hynny gyda neb o fewn S4C, er bod y diwydiant yng Nghymru i gyd yn gwybod beth oedd wedi cael ei ddweud, wrth bwy yr oedd e wedi cael ei ddweud.', 'She hadn''t shared that with anyone within S4C, although the wider industry in Wales all knew what had been said and to whom.', 'contribution 555245 · part 4/11', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC099-S0355', 'cym_n_for_eng:senedd-s4c-steve', 99, 355, 355, 'Rhodri Williams', 'Roedd e''n cael ei adrodd yn y wasg bron cyn i ni glywed amdano.', 'It was being reported in the press almost before we''d heard about these events.', 'contribution 555245 · part 5/11', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC099-S0356', 'cym_n_for_eng:senedd-s4c-steve', 99, 356, 356, 'Rhodri Williams', 'Felly, o dan yr amgylchiadau hynny, ac ar ôl derbyn cyngor ar broses a chyngor ar ddeddfwriaeth gyflogaeth a''r camau priodol i gymryd, fe gymerais i''r penderfyniad bod yn rhaid gweithredu''n syth er mwyn diogelu enw da S4C.', 'So, under those circumstances, and having receiving advice on procedure and on employment law and the appropriate steps to be taken, I took the decision that action had to be taken immediately in order to safeguard the reputation of S4C.', 'contribution 555245 · part 6/11', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC099-S0357', 'cym_n_for_eng:senedd-s4c-steve', 99, 357, 357, 'Rhodri Williams', 'Fel y cafodd ei gyfeirio ato''n gynt, dwi wedi bod yn y busnes yma am flynyddoedd lawer ac erioed wedi dod ar draws achos o uchel-swyddog yn ymddwyn yn y ffordd yna.', 'As was mentioned earlier, I have been in this business for many years and have never come across a case of a senior official behaving in that way.', 'contribution 555245 · part 7/11', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC099-S0358', 'cym_n_for_eng:senedd-s4c-steve', 99, 358, 358, 'Rhodri Williams', 'Pan fyddai''n dod, pe bai prif weithredwr newydd yn penderfynu bod angen—.', 'If the new chief executive were to decide—.', 'contribution 555245 · part 8/11', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC099-S0359', 'cym_n_for_eng:senedd-s4c-steve', 99, 359, 359, 'Rhodri Williams', 'Hynny yw, byddan nhw''n penodi rhywun, oni fyddan nhw, pe bai''n prif swyddog cynnwys fyddai fe neu gyfarwyddwr cynnwys, cyfarwyddwr rhaglenni—mae yna deitlau gwahanol.', 'Of course, they will appoint somebody, whether that person will be a chief content officer or a director of content or a director of programming—there are all sorts of possible titles.', 'contribution 555245 · part 9/11', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC099-S0360', 'cym_n_for_eng:senedd-s4c-steve', 99, 360, 360, 'Rhodri Williams', 'Pan fydd prif weithredwr newydd yn penodi, byddwn i''n disgwyl, fel mae''n digwydd, y byddai''r cadeirydd, pwy bynnag fyddai hwnna, yn cael ei wahodd i''r broses honno hefyd.', 'When a new chief executive appoints, I would expect, as it happens, that the chair, whoever he or she may be, would be invited into that process.', 'contribution 555245 · part 10/11', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC099-S0361', 'cym_n_for_eng:senedd-s4c-steve', 99, 361, 361, 'Rhodri Williams', 'Roeddwn i''n rhan o benodi Llinos Griffin-Williams i S4C, gan fod y swydd yn un o''r swyddi hynny sydd yn cario''r dyletswyddau ychwanegol o fod yn gyfarwyddwr gweithredol o''r bwrdd unedol cysgodol.', 'I was involved in the process of appointing Llinos Griffin-Williams to S4C, because the post was one of those posts that carries the additional duties of being an executive director of the shadow unitary board.', 'contribution 555245 · part 11/11', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC100-S0362', 'cym_n_for_eng:senedd-s4c-steve', 100, 362, 362, 'Rhodri Williams', 'Sori, pam dwi wedi troi i''r Saesneg, dwi ddim yn gwybod.', 'Sorry, I don''t know why I turned to English there.', 'contribution 555366 · part 1/3', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC100-S0363', 'cym_n_for_eng:senedd-s4c-steve', 100, 363, 363, 'Rhodri Williams', 'Bydd y bwrdd yn trafod hynny pythefnos i heddiw.', 'The board will discuss that a fortnight today.', 'contribution 555366 · part 2/3', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC100-S0364', 'cym_n_for_eng:senedd-s4c-steve', 100, 364, 364, 'Rhodri Williams', 'O ran pa mor bell y gallem ni fynd, fyddwn i ddim yn meddwl y byddai apwyntiad yn cael ei wneud, a bod yn berffaith onest, yn ystod gweddill fy nghyfnod i; fyddwn i ddim yn disgwyl y gallai ddigwydd o fewn y cyfnod hwnnw, ta beth.', 'In terms of how far we could go, I wouldn''t think that an appointment would be made, if I''m perfectly honest, during the remainder of my term of office; I wouldn''t expect it to happen within that period.', 'contribution 555366 · part 3/3', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC101-S0365', 'cym_n_for_eng:senedd-s4c-steve', 101, 365, 365, 'Delyth Jewell', 'Diolch.', 'Thank you.', 'contribution 555367 · part 1/5', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC101-S0366', 'cym_n_for_eng:senedd-s4c-steve', 101, 366, 366, 'Delyth Jewell', 'Dŷn ni''n ymwybodol iawn o faint o amser ychwanegol dŷch chi wedi aros gyda ni—diolch yn fawr iawn.', 'We''re very aware of how long you''ve stayed with us—thank you very much.', 'contribution 555367 · part 2/5', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC101-S0367', 'cym_n_for_eng:senedd-s4c-steve', 101, 367, 367, 'Delyth Jewell', 'Jest dau gwestiwn cryno iawn gen i, ar y diwedd.', 'I have two very brief questions, at the end.', 'contribution 555367 · part 3/5', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC101-S0368', 'cym_n_for_eng:senedd-s4c-steve', 101, 368, 368, 'Delyth Jewell', 'Roeddech chi wedi sôn wrth Alun, ac roedd e wedi''i godi ddoe, am y ffaith eich bod chi wedi gofyn am sawl cyfarfod gyda DCMS a bod hynny ddim wedi digwydd.', 'You mentioned to Alun, and this was raised yesterday, that you''d asked for many meetings with DCMS and that that hadn''t happened.', 'contribution 555367 · part 4/5', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC101-S0369', 'cym_n_for_eng:senedd-s4c-steve', 101, 369, 369, 'Delyth Jewell', 'A ydych chi''n meddwl ei fod e''n briodol, felly, taw''r Secretary of State sydd â''r pwerau yn y sefyllfa yma, os nad ydy''r Secretary of State yn dangos y diddordeb i eisiau cael cyfarfod?', 'Do you think it''s appropriate, therefore, that it''s the Secretary of State who has the powers in this situation if the Secretary of State doesn''t show an interest in having a meeting?', 'contribution 555367 · part 5/5', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC102-S0370', 'cym_n_for_eng:senedd-s4c-steve', 102, 370, 370, 'Rhodri Williams', 'Dwi''n credu bod hwnna y tu hwnt i fy nyletswyddau i i fynegi barn ar bwy ddylai—.', 'I think that''s beyond my responsibilities in terms of expressing a view on who should—.', 'contribution 555368 · part 1/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC102-S0371', 'cym_n_for_eng:senedd-s4c-steve', 102, 371, 371, 'Rhodri Williams', 'Hynny yw, dyna''r fframwaith rŷn ni''n gweithio ynddo fe—', 'In other words, that''s the framework that we''re working within—', 'contribution 555368 · part 2/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC103-S0372', 'cym_n_for_eng:senedd-s4c-steve', 103, 372, 372, 'Delyth Jewell', 'Ond dydy''r fframwaith ddim, efallai, yn gweithio''n dda ar hyn o bryd, fel y mae.', 'But perhaps the framework isn''t working as well as it should at the moment.', 'contribution 555369 · part 1/1', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC104-S0373', 'cym_n_for_eng:senedd-s4c-steve', 104, 373, 373, 'Rhodri Williams', 'Fel y dywedais i, rŷn ni wedi cwrdd yn achlysurol â rhai Gweinidogion o''r adran, ond fel y dywedais i, pan gynigiais i ein bod ni''n cyfarfod â''r Ysgrifennydd Gwladol i drafod y mater penodol yma, fel mae''n digwydd, gafodd y cynnig ddim ei dderbyn.', 'As I said, we have occasionally met with some Ministers from the department, but as I said, when I proposed that we should meet the Secretary of State to discuss this specific issue, as it happens, that offer was not accepted.', 'contribution 555370 · part 1/3', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC104-S0374', 'cym_n_for_eng:senedd-s4c-steve', 104, 374, 374, 'Rhodri Williams', 'Mae''n ymddangos i fi pan roedd y broses yn mynd yn ei blaen, doedd dim llawer o ddiddordeb, ond oherwydd y ffordd mae pethau wedi digwydd—a dyw''r ffordd hwnnw ddim y ffordd y byddwn i wedi dychmygu y byddai pethau wedi digwydd pan ddechreuodd y broses—mae gan bawb, bellach, ddiddordeb mewn pob un agwedd ar hwn.', 'It appears to me that when this process was ongoing, there wasn''t a great deal of interest shown in it, but because of the way things have panned out—and that isn''t how I would have imagined things developing when this whole process started—everyone, now, is taking an interest in all aspects of this.', 'contribution 555370 · part 2/3', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC104-S0375', 'cym_n_for_eng:senedd-s4c-steve', 104, 375, 375, 'Rhodri Williams', 'Mae hynny i''w ddisgwyl, onid yw e?', 'That''s to be expected, isn''t it?', 'contribution 555370 · part 3/3', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC105-S0376', 'cym_n_for_eng:senedd-s4c-steve', 105, 376, 376, 'Delyth Jewell', 'Diolch.', 'Thank you.', 'contribution 555392 · part 1/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC105-S0377', 'cym_n_for_eng:senedd-s4c-steve', 105, 377, 377, 'Delyth Jewell', 'Jest y cwestiwn olaf: oes yna unrhyw beth dŷch chi''n difaru am yr holl sefyllfa?', 'Just the final question: is there anything that you regret about the whole situation?', 'contribution 555392 · part 2/2', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC106-S0378', 'cym_n_for_eng:senedd-s4c-steve', 106, 378, 378, 'Rhodri Williams', 'Oes.', 'Yes.', 'contribution 555393 · part 1/13', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC106-S0379', 'cym_n_for_eng:senedd-s4c-steve', 106, 379, 379, 'Rhodri Williams', 'Dwi''n difaru y pwynt yma rŷn ni wedi bod yn ei drafod nad oedden ni fel bwrdd yn ymwybodol o''r pryderon yn gynt.', 'I regret this point that we''ve been discussing that we as a board weren''t aware of these concerns at an earlier stage.', 'contribution 555393 · part 2/13', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC106-S0380', 'cym_n_for_eng:senedd-s4c-steve', 106, 380, 380, 'Rhodri Williams', 'Dwi yn difaru wrth edrych nôl fod y cylch gorchwyl wnaethon ni ei gytuno gyda Capital Law yn un oedd yn caniatáu i''r broses gymryd yn hir iawn.', 'I do regret, with hindsight, that the remit that we agreed with Capital Law was one that allowed the process to take a long period of time.', 'contribution 555393 · part 3/13', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC106-S0381', 'cym_n_for_eng:senedd-s4c-steve', 106, 381, 381, 'Rhodri Williams', 'Roedd yna resymau da.', 'There were reasons for that.', 'contribution 555393 · part 4/13', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC106-S0382', 'cym_n_for_eng:senedd-s4c-steve', 106, 382, 382, 'Rhodri Williams', 'Oherwydd y ffactor ofn yma dwi wedi cyfeirio ato fe, roedd hwnna''n rhan bwysig iawn o lunio''r cylch gorchwyl mewn termau eang iawn, oedd yn caniatáu, wrth gwrs, i bawb gyfrannu ato fe.', 'Because of this fear factor that I have referred to, that was a very important part of drawing up the remit in very broad terms that, of course, then allowed everyone to contribute to this process.', 'contribution 555393 · part 5/13', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC106-S0383', 'cym_n_for_eng:senedd-s4c-steve', 106, 383, 383, 'Rhodri Williams', 'Felly, mewn ffordd, fe greon ni broblem i ni''n hunain.', 'So, in a way, we created a problem for ourselves.', 'contribution 555393 · part 6/13', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC106-S0384', 'cym_n_for_eng:senedd-s4c-steve', 106, 384, 384, 'Rhodri Williams', 'Doedd cwyn BECTU ddim yn ymwneud â''r bwrdd, doedd e ddim yn ymwneud â llywodraethiant; roedd e''n ymwneud â''r tîm rheoli, fel roedd e wedi cael ei gyfeirio ato fe, er nad pob aelod o''r tîm rheoli oedd dan sylw, ond oherwydd bod dim modd bod yn benodol ynglŷn â chwynion, byddai fe ddim wedi bod yn briodol i enwi unigolion.', 'The BECTU complaint didn''t refer to the board or to governance; it related to the management team, as it was referred to, although not every member of that management team was involved, but they couldn''t be specific about complaints, and it wouldn''t have been appropriate to name individuals in that scenario.', 'contribution 555393 · part 7/13', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC106-S0385', 'cym_n_for_eng:senedd-s4c-steve', 106, 385, 385, 'Rhodri Williams', 'Roedd BECTU wedi bod yn ofalus iawn yn hynny.', 'BECTU had been very careful in that regard.', 'contribution 555393 · part 8/13', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC106-S0386', 'cym_n_for_eng:senedd-s4c-steve', 106, 386, 386, 'Rhodri Williams', 'Ond, wrth gwrs, fe wnaeth hynny olygu bod y broses yn un hirach a bod y broses yn caniatáu i bobl oedd, mewn gwirionedd, yn wrthrychau''r cwynion i fod yn cyfrannu ati hi.', 'But, of course, that did mean that the process was lengthier and that the process did allow people who were the subjects of complaints to be contributing to it.', 'contribution 555393 · part 9/13', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC106-S0387', 'cym_n_for_eng:senedd-s4c-steve', 106, 387, 387, 'Rhodri Williams', 'Dwi''n credu y byddai fe wedi bod yn fwy llesol, efallai, i''n staff ni ac iechyd meddwl ein staff ni trwy''r cyfnod yma, pe baem ni wedi cytuno ar gylch gorchwyl a oedd yn ffocysu, efallai, ar yr hyn oedd BECTU yn cwyno amdano fe, yn hytrach na dweud, ''Dewch aton ni i siarad am unrhyw beth ŷch chi''n moyn.''', 'I do believe that it would have been more beneficial, perhaps, for our staff and for the mental health of our staff throughout this period, if we had agreed a remit that focused more on what BECTU were complaining about, rather than saying, ''Come to us to talk about anything that''s on your mind.''', 'contribution 555393 · part 10/13', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC106-S0388', 'cym_n_for_eng:senedd-s4c-steve', 106, 388, 388, 'Rhodri Williams', 'Ond gyda''r wybodaeth oedd gyda ni ar y pryd, roeddwn i''n ddigon hapus ar y pryd bod rhaid rhoi proses mewn lle oedd yn un agored iawn, er mwyn sicrhau bod gan bobl yr hyder i gyfrannu ati hi.', 'But, with the information that we had at the time, I was quite content that we needed to put a process in place that was very open, in order to ensure that people had the confidence to contribute to it.', 'contribution 555393 · part 11/13', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC106-S0389', 'cym_n_for_eng:senedd-s4c-steve', 106, 389, 389, 'Rhodri Williams', 'Ond ydw i''n difaru hynny?', 'But do I regret that now?', 'contribution 555393 · part 12/13', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC106-S0390', 'cym_n_for_eng:senedd-s4c-steve', 106, 390, 390, 'Rhodri Williams', 'Ydw.', 'Yes.', 'contribution 555393 · part 13/13', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC107-S0391', 'cym_n_for_eng:senedd-s4c-steve', 107, 391, 391, 'Delyth Jewell', 'Diolch ichi.', 'Thank you.', 'contribution 555394 · part 1/4', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC107-S0392', 'cym_n_for_eng:senedd-s4c-steve', 107, 392, 392, 'Delyth Jewell', 'Rwy''n ddiolchgar iawn, dŷn ni i gyd yn ddiolchgar iawn, am yr amser ychwanegol dŷch chi wedi ei roi i ni y prynhawn yma.', 'We''re very grateful for the additional time you''ve provided this afternoon.', 'contribution 555394 · part 2/4', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC107-S0393', 'cym_n_for_eng:senedd-s4c-steve', 107, 393, 393, 'Delyth Jewell', 'Bydd transgript o''r hyn sydd wedi cael ei ddweud yn cael ei ddanfon atoch chi i chi nodi ei fod e yn gofnod teg o beth sydd wedi cael ei ddweud, ac efallai bydd ychydig o gwestiynau technegol doedden ni ddim wedi cael cyfle i fynd i mewn iddyn nhw y byddwn ni eisiau ysgrifennu atoch chi yn eu cylch.', 'There will be a transcript of the meeting sent to you to ensure that it''s a fair reflection of what''s been said, and perhaps there will be some technical questions that we haven''t been able to ask, and we''ll want to write to you about those.', 'contribution 555394 · part 3/4', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC107-S0394', 'cym_n_for_eng:senedd-s4c-steve', 107, 394, 394, 'Delyth Jewell', 'Ond diolch yn fawr iawn ichi am fod gyda ni y prynhawn yma.', 'But thank you very much for being with us this afternoon.', 'contribution 555394 · part 4/4', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC108-S0395', 'cym_n_for_eng:senedd-s4c-steve', 108, 395, 395, 'Rhodri Williams', 'Diolch yn fawr iawn i chi i gyd am eich amser a''r ffordd ŷch chi wedi mynd ati i''n holi ni.', 'Thank you all very much for your time and for the way in which you have questioned us this afternoon.', 'contribution 555395 · part 1/4', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC108-S0396', 'cym_n_for_eng:senedd-s4c-steve', 108, 396, 396, 'Rhodri Williams', 'Dwi wedi dweud yn y pwyllgor yma o''r blaen ein bod ni yn gwerthfawrogi a bob amser yn barod i gael ein dal i gyfrif gennych chi fel Aelodau etholedig.', 'I have said in this committee previously that do we appreciate and are always willing to be held to account by you as elected Members.', 'contribution 555395 · part 2/4', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC108-S0397', 'cym_n_for_eng:senedd-s4c-steve', 108, 397, 397, 'Rhodri Williams', 'Er gwaethaf y ffaith bod yr amgylchiadau yn rhai amhleserus dros ben, dwi yn ddiolchgar iawn am y modd ŷch chi wedi holi''r cwestiynau yna i ni ac ymdrin â ni heddiw.', 'Despite the fact that the circumstances are unpleasant, I am grateful for the way in which you have asked your questions and have dealt with us today.', 'contribution 555395 · part 3/4', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC108-S0398', 'cym_n_for_eng:senedd-s4c-steve', 108, 398, 398, 'Rhodri Williams', 'Diolch yn fawr iawn.', 'Thank you very much.', 'contribution 555395 · part 4/4', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO listening_pod_sentences (id, pod_id, scene_number, sentence_number, global_order, speaker, target_text, known_text, beat_label, glue_to_next, rerecord_wanted) VALUES ('cym_n_for_eng:senedd-s4c-steve:SC109-S0399', 'cym_n_for_eng:senedd-s4c-steve', 109, 399, 399, 'Delyth Jewell', 'Diolch yn fawr.', 'Thank you very much.', 'contribution 555396 · part 1/1', false, '{"known": "human_aran_cym_n"}'::jsonb) ON CONFLICT (id) DO NOTHING;
